issues":[]},"estimatedDifficulty":"hard","requestedDifficulty":"hard","difficultyReasons":["출력값의 범위 조건을 입력의 구간으로 되돌리고(음수 기울기면 방향 반전) 정수·홀짝 제약으로 후보를 걸러냄 — medium 은 출력값 하나에서 x 를 구함"],"distractors":[],"independentReview":{"pickedIndex":null,"pickedAnswer":null,"agrees":true,"confidence":"high","flags":[]},"needsReview":false,"needsReviewReasons":[],"calibrated":false,"reviewedAt":"1970-01-01T00:00:00.000Z","mockExamGeneration":{"difficultyStatus":"provisional_ai","source":"compiler_archetype","archetypeId":"lf.find_x_for_value.constraint_select","operator":"constraint_select","kind":"find_x_for_value","extraThinking":"출력값의 범위 조건을 입력의 구간으로 되돌리고(음수 기울기면 방향 반전) 정수·홀짝 제약으로 후보를 걸러냄 — medium 은 출력값 하나에서 x 를 구함","concepts":["출력값 범위에서 입력 범위","이중 부등식","정수·홀짝 제약"],"steps":5,"mediumSteps":1,"seed":820000,"variant":"range_with_parity","verification":{"method":"verification_js","verified":6,"correctOption":"6"},"runId":"sat-math-hard5","gid":"83e8368b-c464-5f10-a073-ed59c6bac632","intendedSkill":"linear_functions","recipeId":"lf.find_x_for_value.constraint_select","recipeCheck":{"source":"compiler_archetype","compliance":{"met":3,"minMet":2,"of":3,"ok":true}},"hardBasis":"compiler_archetype","review":null}}},{"gid":"f89c73dc-3b3e-513f-a95d-c2753971caa4","subject":"SAT Math","format":"spr","skillType":"Algebra (선형식·연립·부등식)","difficulty":"hard","skill":"linear_functions","examSystem":"sat_math","createdVia":"compiler","subpattern":"lf.slope_from_two_points.compose_kind/parallel_intercept","group":"lf.slope_from_two_points.compose_kind","passage":"Two points on line r are $(-1, 5)$ and $(0, 8)$. The point $(-1, -2)$ lies on line s, which is everywhere parallel to line r.","question":"Where does line s meet the y-axis? Give the y-coordinate.","options":null,"correctIndex":null,"answers":["1"],"explanation":"(1) r 의 기울기는 $(8 - 5) / (0 - (-1)) = 3$ 이다. (2) 평행한 직선은 기울기가 같으므로 s 의 기울기는 3 이다. (3) s 은 점 (-1, -2) 를 지나므로 $-2 = 3\\cdot (-1) + b$ 이다. (4) 3·(-1) = -3 이다. (5) b = -2 - (-3) = 1 이다. 따라서 정답은 1이다.","explanationEn":"(1) Find the first slope. (2) Find the second slope. (3) Substitute the point. (4) Compute the product. (5) Solve for b. So the answer is 1.","figure":null,"statements":null,"evidenceTarget":null,"evidenceSpan":null,"answerRationale":null,"distractorErrorTypes":null,"renderCheck":{"ok":true,"renderer":"std-1","checkedAt":"2026-10-20T16:19:24.595Z","issues":[]},"publish":true,"quality":{"contract":{"ok":true,"issues":[]},"estimatedDifficulty":"hard","requestedDifficulty":"hard","difficultyReasons":["기울기를 구한 뒤 평행·수직 관계(같은 기울기·음의 역수)를 적용하고 한 점에서 절편을 역산하는 합성 — medium 은 두 점으로 기울기만 구함"],"distractors":[],"independentReview":{"pickedIndex":null,"pickedAnswer":null,"agrees":true,"confidence":"high","flags":[]},"needsReview":false,"needsReviewReasons":[],"calibrated":false,"reviewedAt":"1970-01-01T00:00:00.000Z","mockExamGeneration":{"difficultyStatus":"provisional_ai","source":"compiler_archetype","archetypeId":"lf.slope_from_two_points.compose_kind","operator":"compose_kind","kind":"slope_from_two_points","extraThinking":"기울기를 구한 뒤 평행·수직 관계(같은 기울기·음의 역수)를 적용하고 한 점에서 절편을 역산하는 합성 — medium 은 두 점으로 기울기만 구함","concepts":["두 점으로 기울기","평행·수직 직선의 기울기","점과 기울기로 절편 구하기"],"steps":5,"mediumSteps":1,"seed":820000,"variant":"parallel_intercept","verification":{"method":"verification_js","verified":1,"correctOption":"1"},"runId":"sat-math-hard5","gid":"f89c73dc-3b3e-513f-a95d-c2753971caa4","intendedSkill":"linear_functions","recipeId":"lf.slope_from_two_points.compose_kind","recipeCheck":{"source":"compiler_archetype","compliance":{"met":3,"minMet":2,"of":3,"ok":true}},"hardBasis":"compiler_archetype","review":null}}},{"gid":"54d94d88-7371-5a8b-a5da-0964d2dd0376","subject":"SAT Math","format":"mc","skillType":"Algebra (선형식·연립·부등식)","difficulty":"hard","skill":"linear_functions","examSystem":"sat_math","createdVia":"compiler","subpattern":"lf.slope_from_two_points.repr_shift/intercepts_of_standard_form","group":"lf.slope_from_two_points.repr_shift","passage":"The graph of the equation $x + y = -1$ crosses the x-axis at point P and the y-axis at point Q.","question":"What is the slope of the segment joining the two intercepts?","options":["1","-1","-2","0"],"correctIndex":1,"answers":null,"explanation":"(1) y = 0 을 대입하면 P 의 x 좌표는 -1/1 = -1 이므로 P = (-1, 0) 이다. (2) x = 0 을 대입하면 Q 의 y 좌표는 -1/1 = -1 이므로 Q = (0, -1) 이다. (3) 기울기는 $(y_Q - y_P)/(x_Q - x_P)$ 이다. (4) 대입하면 $(-1 - 0) / (0 - (-1)) = -1/1$ 이다. (5) 약분하면 -1 이다. 따라서 정답은 -1이다.","explanationEn":"(1) Find the x-intercept. (2) Find the y-intercept. (3) Write the slope formula. (4) Substitute. (5) Simplify. So the answer is -1.","figure":null,"statements":null,"evidenceTarget":null,"evidenceSpan":null,"answerRationale":null,"distractorErrorTypes":null,"renderCheck":{"ok":true,"renderer":"std-1","checkedAt":"2026-10-20T16:19:24.595Z","issues":[]},"publish":true,"quality":{"contract":{"ok":true,"issues":[]},"estimatedDifficulty":"hard","requestedDifficulty":"hard","difficultyReasons":["방정식을 축과의 교점(좌표)으로 번역한 뒤 두 점으로 기울기를 구함 — medium 은 두 점이 주어진 기울기 계산"],"distractors":[],"independentReview":{"pickedIndex":null,"pickedAnswer":null,"agrees":true,"confidence":"high","flags":[]},"needsReview":false,"needsReviewReasons":[],"calibrated":false,"reviewedAt":"1970-01-01T00:00:00.000Z","mockExamGeneration":{"difficultyStatus":"provisional_ai","source":"compiler_archetype","archetypeId":"lf.slope_from_two_points.repr_shift","operator":"repr_shift","kind":"slope_from_two_points","extraThinking":"방정식을 축과의 교점(좌표)으로 번역한 뒤 두 점으로 기울기를 구함 — medium 은 두 점이 주어진 기울기 계산","concepts":["축 절편 구하기","두 점으로 기울기"],"steps":5,"mediumSteps":1,"seed":820000,"variant":"intercepts_of_standard_form","verification":{"method":"verification_js","verified":-1,"correctOption":"-1"},"runId":"sat-math-hard5","gid":"54d94d88-7371-5a8b-a5da-0964d2dd0376","intendedSkill":"linear_functions","recipeId":"lf.slope_from_two_points.repr_shift","recipeCheck":{"source":"compiler_archetype","compliance":{"met":2,"minMet":2,"of":2,"ok":true}},"hardBasis":"compiler_archetype","review":null}}},{"gid":"daf868ae-3aed-5765-a0ab-12ced96503c1","subject":"SAT Math","format":"mc","skillType":"Algebra (선형식·연립·부등식)","difficulty":"hard","skill":"linear_functions","examSystem":"sat_math","createdVia":"compiler","subpattern":"lf.slope_from_two_points.compare_scenarios/slope_difference","group":"lf.slope_from_two_points.compare_scenarios","passage":"Line ℓ passes through $(-4, -6)$ and $(-3, -8)$. Line m passes through $(-3, -8)$ and $(1, -28)$.","question":"The slope of ℓ is how much larger than the slope of m?","options":["-3","-2","3","-7"],"correctIndex":2,"answers":null,"explanation":"(1) ℓ: $(-8 - (-6)) / (-3 - (-4)) = -2$ 이다. (2) m: $(-28 - (-8)) / (1 - (-3)) = -5$ 이다. (3) ℓ 의 기울기가 더 크다. (4) 차는 -2 - (-5) 이다. (5) 계산하면 3 이다. 따라서 정답은 3이다.","explanationEn":"(1) First slope. (2) Second slope. (3) Compare. (4) Set up the difference. (5) Subtract. So the answer is 3.","figure":null,"statements":null,"evidenceTarget":null,"evidenceSpan":null,"answerRationale":null,"distractorErrorTypes":null,"renderCheck":{"ok":true,"renderer":"std-1","checkedAt":"2026-10-20T16:19:24.596Z","issues":[]},"publish":true,"quality":{"contract":{"ok":true,"issues":[]},"estimatedDifficulty":"hard","requestedDifficulty":"hard","difficultyReasons":["서로 다른 두 직선의 기울기를 독립적으로 구해 비교(차) — medium 은 기울기 하나"],"distractors":[],"independentReview":{"pickedIndex":null,"pickedAnswer":null,"agrees":true,"confidence":"high","flags":[]},"needsReview":false,"needsReviewReasons":[],"calibrated":false,"reviewedAt":"1970-01-01T00:00:00.000Z","mockExamGeneration":{"difficultyStatus":"provisional_ai","source":"compiler_archetype","archetypeId":"lf.slope_from_two_points.compare_scenarios","operator":"compare_scenarios","kind":"slope_from_two_points","extraThinking":"서로 다른 두 직선의 기울기를 독립적으로 구해 비교(차) — medium 은 기울기 하나","concepts":["두 점으로 기울기","기울기 비교"],"steps":5,"mediumSteps":1,"seed":820000,"variant":"slope_difference","verification":{"method":"verification_js","verified":3,"correctOption":"3"},"runId":"sat-math-hard5","gid":"daf868ae-3aed-5765-a0ab-12ced96503c1","intendedSkill":"linear_functions","recipeId":"lf.slope_from_two_points.compare_scenarios","recipeCheck":{"source":"compiler_archetype","compliance":{"met":2,"minMet":2,"of":2,"ok":true}},"hardBasis":"compiler_archetype","review":null}}},{"gid":"ebddd84b-b66c-5e61-a128-a80f7f2c1413","subject":"SAT Math","format":"spr","skillType":"Algebra (선형식·연립·부등식)","difficulty":"hard","skill":"linear_functions","examSystem":"sat_math","createdVia":"compiler","subpattern":"lf.interpret_slope.unit_ratio/rate_in_other_units","group":"lf.interpret_slope.unit_ratio","passage":"A delivery drone moves along a straight path. Let $D(t) = 100t + 165$ give its distance from the pilot, in meters, where t is the number of minutes after takeoff.","question":"The distance increases by how many kilometers each hour?","options":null,"correctIndex":null,"answers":["6"],"explanation":"(1) 기울기 100 는 변화율이다: t 가 1 증가할 때 함수값이 100 증가한다. (2) 변화율의 단위를 읽는다(함수값 단위 / 시간 단위). (3) 단위 환산 규칙을 정한다: 1시간 = 60분, 1 km = 1000 m. (4) 시간 단위와 양의 단위를 순서대로 환산한다. (5) 변화율은 6 이다. 따라서 정답은 6이다.","explanationEn":"(1) The slope is the rate of change. (2) Read the units of the rate. (3) Choose the conversion rules. (4) Convert time and quantity units. (5) Compute. So the answer is 6.","figure":null,"statements":null,"evidenceTarget":null,"evidenceSpan":null,"answerRationale":null,"distractorErrorTypes":null,"renderCheck":{"ok":true,"renderer":"std-1","checkedAt":"2026-10-20T16:19:24.596Z","issues":[]},"publish":true,"quality":{"contract":{"ok":true,"issues":[]},"estimatedDifficulty":"hard","requestedDifficulty":"hard","difficultyReasons":["기울기를 변화율로 해석한 뒤 시간·양의 단위를 환산(분→시간, m→km 등) — medium 은 기울기의 의미를 같은 단위로 해석"],"distractors":[],"independentReview":{"pickedIndex":null,"pickedAnswer":null,"agrees":true,"confidence":"high","flags":[]},"needsReview":false,"needsReviewReasons":[],"calibrated":false,"reviewedAt":"1970-01-01T00:00:00.000Z","mockExamGeneration":{"difficultyStatus":"provisional_ai","source":"compiler_archetype","archetypeId":"lf.interpret_slope.unit_ratio","operator":"unit_ratio","kind":"interpret_slope","extraThinking":"기울기를 변화율로 해석한 뒤 시간·양의 단위를 환산(분→시간, m→km 등) — medium 은 기울기의 의미를 같은 단위로 해석","concepts":["기울기의 의미(변화율)","단위 환산"],"steps":5,"mediumSteps":3,"seed":820000,"variant":"rate_in_other_units","verification":{"method":"verification_js","verified":6,"correctOption":"6"},"runId":"sat-math-hard5","gid":"ebddd84b-b66c-5e61-a128-a80f7f2c1413","intendedSkill":"linear_functions","recipeId":"lf.interpret_slope.unit_ratio","recipeCheck":{"source":"compiler_archetype","compliance":{"met":2,"minMet":2,"of":2,"ok":true}},"hardBasis":"compiler_archetype","review":null}}},{"gid":"b6b4f648-b1f6-5ef8-abcc-01acd3d06c93","subject":"SAT Math","format":"mc","skillType":"Algebra (선형식·연립·부등식)","difficulty":"hard","skill":"linear_functions","examSystem":"sat_math","createdVia":"compiler","subpattern":"lf.interpret_slope.repr_shift/rate_from_two_observations","group":"lf.interpret_slope.repr_shift","passage":"A warehouse follows a linear pattern. Measurements show 40 boxes after 4 days and 64 boxes after 8 days.","question":"By how many boxes will the inventory increase over 8 days?","options":["72","6","48","24"],"correctIndex":2,"answers":null,"explanation":"(1) x 의 변화량은 8 - 4 = 4 이다. (2) y 의 변화량은 64 - 40 = 24 이다. (3) 변화율(기울기)은 24/4 = 6 이다. (4) 기울기 6 은 한 단위마다 6 증가한다는 뜻이다. (5) 8 단위 동안은 6 × 8 = 48 이다. 따라서 정답은 48이다.","explanationEn":"(1) Find the change in x. (2) Find the change in y. (3) Compute the rate. (4) Interpret the slope. (5) Scale to the interval. So the answer is 48.","figure":null,"statements":null,"evidenceTarget":null,"evidenceSpan":null,"answerRationale":null,"distractorErrorTypes":null,"renderCheck":{"ok":true,"renderer":"std-1","checkedAt":"2026-10-20T16:19:24.596Z","issues":[]},"publish":true,"quality":{"contract":{"ok":true,"issues":[]},"estimatedDifficulty":"hard","requestedDifficulty":"hard","difficultyReasons":["표(두 관측값)를 변화율로 번역하고 그 해석을 다른 구간에 적용 — medium 은 주어진 식에서 기울기의 의미를 읽음"],"distractors":[],"independentReview":{"pickedIndex":null,"pickedAnswer":null,"agrees":true,"confidence":"high","flags":[]},"needsReview":false,"needsReviewReasons":[],"calibrated":false,"reviewedAt":"1970-01-01T00:00:00.000Z","mockExamGeneration":{"difficultyStatus":"provisional_ai","source":"compiler_archetype","archetypeId":"lf.interpret_slope.repr_shift","operator":"repr_shift","kind":"interpret_slope","extraThinking":"표(두 관측값)를 변화율로 번역하고 그 해석을 다른 구간에 적용 — medium 은 주어진 식에서 기울기의 의미를 읽음","concepts":["표→변화율","기울기의 의미","변화량 = 기울기 × 증가량"],"steps":5,"mediumSteps":3,"seed":820000,"variant":"rate_from_two_observations","verification":{"method":"verification_js","verified":48,"correctOption":"48"},"runId":"sat-math-hard5","gid":"b6b4f648-b1f6-5ef8-abcc-01acd3d06c93","intendedSkill":"linear_functions","recipeId":"lf.interpret_slope.repr_shift","recipeCheck":{"source":"compiler_archetype","compliance":{"met":3,"minMet":2,"of":3,"ok":true}},"hardBasis":"compiler_archetype","review":null}}},{"gid":"416c2c64-ac1c-5c73-a8b4-d49f96b6f29f","subject":"SAT Math","format":"mc","skillType":"Algebra (선형식·연립·부등식)","difficulty":"hard","skill":"linear_functions","examSystem":"sat_math","createdVia":"compiler","subpattern":"lf.interpret_slope.compare_scenarios/difference_of_changes","group":"lf.interpret_slope.compare_scenarios","passage":"A and B are two items that are being tracked. The collection of A is modeled by $A(t) = 11t + 59$, and the collection of B is modeled by $B(t) = 2t + 68$, in books, where t is the number of months.","question":"During 4 months, by how many more books does A's collection change than B's?","options":["27","44","9","36"],"correctIndex":3,"answers":null,"explanation":"(1) A 의 기울기는 11 이므로 1 month 마다 11 씩 변한다. (2) B 의 기울기는 2 이므로 1 month 마다 2 씩 변한다. (3) 4 months 동안 A 는 44, B 는 8 변한다(절편은 변화량에 영향을 주지 않는다). (4) 두 변화량의 차를 구한다. (5) 44 - 8 = 36 이다. 따라서 정답은 36이다.","explanationEn":"(1) Read A's rate. (2) Read B's rate. (3) Scale by the time. (4) Subtract. (5) Compute. So the answer is 36.","figure":null,"statements":null,"evidenceTarget":null,"evidenceSpan":null,"answerRationale":null,"distractorErrorTypes":null,"renderCheck":{"ok":true,"renderer":"std-1","checkedAt":"2026-10-20T16:19:24.596Z","issues":[]},"publish":true,"quality":{"contract":{"ok":true,"issues":[]},"estimatedDifficulty":"hard","requestedDifficulty":"hard","difficultyReasons":["두 모델의 기울기를 각각 해석하고 변화량을 비교(절편은 변화량에 영향이 없음을 판단) — medium 은 모델 하나의 기울기 해석"],"distractors":[],"independentReview":{"pickedIndex":null,"pickedAnswer":null,"agrees":true,"confidence":"high","flags":[]},"needsReview":false,"needsReviewReasons":[],"calibrated":false,"reviewedAt":"1970-01-01T00:00:00.000Z","mockExamGeneration":{"difficultyStatus":"provisional_ai","source":"compiler_archetype","archetypeId":"lf.interpret_slope.compare_scenarios","operator":"compare_scenarios","kind":"interpret_slope","extraThinking":"두 모델의 기울기를 각각 해석하고 변화량을 비교(절편은 변화량에 영향이 없음을 판단) — medium 은 모델 하나의 기울기 해석","concepts":["기울기의 의미","두 변화율 비교","변화량 계산"],"steps":5,"mediumSteps":3,"seed":820000,"variant":"difference_of_changes","verification":{"method":"verification_js","verified":36,"correctOption":"36"},"runId":"sat-math-hard5","gid":"416c2c64-ac1c-5c73-a8b4-d49f96b6f29f","intendedSkill":"linear_functions","recipeId":"lf.interpret_slope.compare_scenarios","recipeCheck":{"source":"compiler_archetype","compliance":{"met":3,"minMet":2,"of":3,"ok":true}},"hardBasis":"compiler_archetype","review":null}}},{"gid":"9a50a4de-92bf-517a-a98c-1e6aaa7dc0da","subject":"SAT Math","format":"spr","skillType":"Algebra (선형식·연립·부등식)","difficulty":"hard","skill":"linear_functions","examSystem":"sat_math","createdVia":"compiler","subpattern":"lf.interpret_slope.chain2/slope_relation_then_value","group":"lf.interpret_slope.chain2","passage":"A linear function u is given by $u(x) = -3x - 5$. The graph of v passes through $(4, 9)$, and its slope is twice the opposite of that of u.","question":"What output does v give for an input of -3?","options":null,"correctIndex":null,"answers":["-33"],"explanation":"(1) u 의 기울기는 -3 이다. (2) v 의 기울기는 twice the opposite of -3 = 6 이다. (3) v(x) = 6x + b 로 놓고 점 (4, 9) 를 대입한다. (4) b = 9 - 24 = -15 이다. (5) $v(-3) = 6\\cdot (-3) - 15 = -33$ 이다. 따라서 정답은 -33이다.","explanationEn":"(1) Read the first slope. (2) Translate the relation. (3) Substitute the point. (4) Solve for b. (5) Evaluate. So the answer is -33.","figure":null,"statements":null,"evidenceTarget":null,"evidenceSpan":null,"answerRationale":null,"distractorErrorTypes":null,"renderCheck":{"ok":true,"renderer":"std-1","checkedAt":"2026-10-20T16:19:24.596Z","issues":[]},"publish":true,"quality":{"contract":{"ok":true,"issues":[]},"estimatedDifficulty":"hard","requestedDifficulty":"hard","difficultyReasons":["기울기 사이의 문장 관계(α 배)를 읽어 다음 단계의 입력으로 쓰는 2단계 연쇄 — medium 은 기울기의 의미를 한 번 해석"],"distractors":[],"independentReview":{"pickedIndex":null,"pickedAnswer":null,"agrees":true,"confidence":"high","flags":[]},"needsReview":false,"needsReviewReasons":[],"calibrated":false,"reviewedAt":"1970-01-01T00:00:00.000Z","mockExamGeneration":{"difficultyStatus":"provisional_ai","source":"compiler_archetype","archetypeId":"lf.interpret_slope.chain2","operator":"chain2","kind":"interpret_slope","extraThinking":"기울기 사이의 문장 관계(α 배)를 읽어 다음 단계의 입력으로 쓰는 2단계 연쇄 — medium 은 기울기의 의미를 한 번 해석","concepts":["기울기 해석","기울기 관계(문장→식)","점과 기울기로 직선 구하기"],"steps":5,"mediumSteps":3,"seed":820000,"variant":"slope_relation_then_value","verification":{"method":"verification_js","verified":-33,"correctOption":"-33"},"runId":"sat-math-hard5","gid":"9a50a4de-92bf-517a-a98c-1e6aaa7dc0da","intendedSkill":"linear_functions","recipeId":"lf.interpret_slope.chain2","recipeCheck":{"source":"compiler_archetype","compliance":{"met":3,"minMet":2,"of":3,"ok":true}},"hardBasis":"compiler_archetype","review":null}}},{"gid":"339ed62e-a4b5-544c-a949-48f5bd57a06d","subject":"SAT Math","format":"mc","skillType":"Algebra (선형식·연립·부등식)","difficulty":"hard","skill":"linear_functions","examSystem":"sat_math","createdVia":"compiler","subpattern":"lf.interpret_intercept.unit_ratio/starting_value_other_units","group":"lf.interpret_intercept.unit_ratio","passage":"A group is hiking. Let $L(t) = 4t + 2$ give the distance walked, in kilometers, where t is the number of hours after noon.","question":"At noon, how far had they walked, in meters?","options":["2","6000","4","2000"],"correctIndex":3,"answers":null,"explanation":"(1) t = 0 일 때 함수값이 y 절편이므로 y 절편은 시작값이다. (2) 시작값은 2 이다. (3) 환산 규칙을 정한다: 1 km = 1000 m. (4) 규칙을 시작값에 적용한다. (5) 결과는 2000 이다. 따라서 정답은 2000이다.","explanationEn":"(1) The intercept is the value at t = 0. (2) Read the starting value. (3) Choose the conversion rule. (4) Apply the conversion. (5) Answer. So the answer is 2000.","figure":null,"statements":null,"evidenceTarget":null,"evidenceSpan":null,"answerRationale":null,"distractorErrorTypes":null,"renderCheck":{"ok":true,"renderer":"std-1","checkedAt":"2026-10-20T16:19:24.596Z","issues":[]},"publish":true,"quality":{"contract":{"ok":true,"issues":[]},"estimatedDifficulty":"hard","requestedDifficulty":"hard","difficultyReasons":["y 절편을 '시작값'으로 해석한 뒤 단위(온도·길이·시간 등)를 환산 — medium 은 절편의 의미를 같은 단위로 해석"],"distractors":[],"independentReview":{"pickedIndex":null,"pickedAnswer":null,"agrees":true,"confidence":"high","flags":[]},"needsReview":false,"needsReviewReasons":[],"calibrated":false,"reviewedAt":"1970-01-01T00:00:00.000Z","mockExamGeneration":{"difficultyStatus":"provisional_ai","source":"compiler_archetype","archetypeId":"lf.interpret_intercept.unit_ratio","operator":"unit_ratio","kind":"interpret_intercept","extraThinking":"y 절편을 '시작값'으로 해석한 뒤 단위(온도·길이·시간 등)를 환산 — medium 은 절편의 의미를 같은 단위로 해석","concepts":["y 절편의 의미(시작값)","단위 환산"],"steps":5,"mediumSteps":2,"seed":820000,"variant":"starting_value_other_units","verification":{"method":"verification_js","verified":2000,"correctOption":"2000"},"runId":"sat-math-hard5","gid":"339ed62e-a4b5-544c-a949-48f5bd57a06d","intendedSkill":"linear_functions","recipeId":"lf.interpret_intercept.unit_ratio","recipeCheck":{"source":"compiler_archetype","compliance":{"met":2,"minMet":2,"of":2,"ok":true}},"hardBasis":"compiler_archetype","review":null}}},{"gid":"2c06c8ea-96a8-514b-a590-16d62f7a0d18","subject":"SAT Math","format":"mc","skillType":"Algebra (선형식·연립·부등식)","difficulty":"hard","skill":"linear_functions","examSystem":"sat_math","createdVia":"compiler","subpattern":"lf.interpret_intercept.repr_shift/extrapolate_to_start","group":"lf.interpret_intercept.repr_shift","passage":"A phone follows a linear pattern. Records show 66 gigabytes after 3 weeks, then 86 gigabytes after 8 weeks.","question":"What does the pattern say the storage in use was at time 0, in gigabytes?","options":["78","62","4","54"],"correctIndex":3,"answers":null,"explanation":"(1) 변화율은 (86 - 66) / (8 - 3) = 4 이다. (2) 식을 y = 4x + b 로 놓는다. (3) (3, 66) 를 대입하면 66 = 4·3 + b 이다. (4) b = 66 - 12 = 54 이다. (5) x = 0 일 때의 값 b = 54 이 시작값이다. 따라서 정답은 54이다.","explanationEn":"(1) Compute the rate. (2) Write the form. (3) Substitute. (4) Solve for b. (5) Interpret the intercept. So the answer is 54.","figure":null,"statements":null,"evidenceTarget":null,"evidenceSpan":null,"answerRationale":null,"distractorErrorTypes":null,"renderCheck":{"ok":true,"renderer":"std-1","checkedAt":"2026-10-20T16:19:24.596Z","issues":[]},"publish":true,"quality":{"contract":{"ok":true,"issues":[]},"estimatedDifficulty":"hard","requestedDifficulty":"hard","difficultyReasons":["표의 두 점을 직선의 식으로 번역한 뒤 t = 0 으로 외삽해 절편의 의미(시작값)를 읽음 — medium 은 식에서 절편 해석"],"distractors":[],"independentReview":{"pickedIndex":null,"pickedAnswer":null,"agrees":true,"confidence":"high","flags":[]},"needsReview":false,"needsReviewReasons":[],"calibrated":false,"reviewedAt":"1970-01-01T00:00:00.000Z","mockExamGeneration":{"difficultyStatus":"provisional_ai","source":"compiler_archetype","archetypeId":"lf.interpret_intercept.repr_shift","operator":"repr_shift","kind":"interpret_intercept","extraThinking":"표의 두 점을 직선의 식으로 번역한 뒤 t = 0 으로 외삽해 절편의 의미(시작값)를 읽음 — medium 은 식에서 절편 해석","concepts":["표→직선의 식","y 절편의 의미(시작값)"],"steps":5,"mediumSteps":2,"seed":820000,"variant":"extrapolate_to_start","verification":{"method":"verification_js","verified":54,"correctOption":"54"},"runId":"sat-math-hard5","gid":"2c06c8ea-96a8-514b-a590-16d62f7a0d18","intendedSkill":"linear_functions","recipeId":"lf.interpret_intercept.repr_shift","recipeCheck":{"source":"compiler_archetype","compliance":{"met":2,"minMet":2,"of":2,"ok":true}},"hardBasis":"compiler_archetype","review":null}}},{"gid":"8e1eba22-af79-5eee-acf6-9b22e93cb8cb","subject":"SAT Math","format":"mc","skillType":"Algebra (선형식·연립·부등식)","difficulty":"hard","skill":"linear_functions","examSystem":"sat_math","createdVia":"compiler","subpattern":"lf.interpret_intercept.inverse/work_backward_to_start","group":"lf.interpret_intercept.inverse","passage":"A phone changes by the same amount every week. It stores 6 additional gigabytes each week. The storage in use is 101 gigabytes after 11 weeks.","question":"How many gigabytes did the storage in use equal before any weeks had passed?","options":["167","35","66","101"],"correctIndex":1,"answers":null,"explanation":"(1) 모델을 y = 6t + b 로 놓는다(증가하므로 기울기는 양수). (2) t = 11 일 때 값은 101 이다. (3) 101 = 6·11 + b 이다. (4) 11 단위 동안의 변화량은 66 이다. (5) b = 101 - 66 = 35 이다. 따라서 정답은 35이다.","explanationEn":"(1) Set up the model with the right sign. (2) Use the given value. (3) Substitute. (4) Compute the total change. (5) Solve for the start. So the answer is 35.","figure":null,"statements":null,"evidenceTarget":null,"evidenceSpan":null,"answerRationale":null,"distractorErrorTypes":null,"renderCheck":{"ok":true,"renderer":"std-1","checkedAt":"2026-10-20T16:19:24.596Z","issues":[]},"publish":true,"quality":{"contract":{"ok":true,"issues":[]},"estimatedDifficulty":"hard","requestedDifficulty":"hard","difficultyReasons":["정방향(시작값→현재값)을 거꾸로 되돌리는 역산에서 증가·감소 방향을 문장으로 판단 — medium 은 식에서 절편 해석"],"distractors":[],"independentReview":{"pickedIndex":null,"pickedAnswer":null,"agrees":true,"confidence":"high","flags":[]},"needsReview":false,"needsReviewReasons":[],"calibrated":false,"reviewedAt":"1970-01-01T00:00:00.000Z","mockExamGeneration":{"difficultyStatus":"provisional_ai","source":"compiler_archetype","archetypeId":"lf.interpret_intercept.inverse","operator":"inverse","kind":"interpret_intercept","extraThinking":"정방향(시작값→현재값)을 거꾸로 되돌리는 역산에서 증가·감소 방향을 문장으로 판단 — medium 은 식에서 절편 해석","concepts":["일차 모델의 시작값","변화 방향(증가·감소) 판단","역산"],"steps":5,"mediumSteps":2,"seed":820000,"variant":"work_backward_to_start","verification":{"method":"verification_js","verified":35,"correctOption":"35"},"runId":"sat-math-hard5","gid":"8e1eba22-af79-5eee-acf6-9b22e93cb8cb","intendedSkill":"linear_functions","recipeId":"lf.interpret_intercept.inverse","recipeCheck":{"source":"compiler_archetype","compliance":{"met":3,"minMet":2,"of":3,"ok":true}},"hardBasis":"compiler_archetype","review":null}}},{"gid":"4cdac8e7-a82b-5179-a8dc-7332e6db175c","subject":"SAT Math","format":"spr","skillType":"Algebra (선형식·연립·부등식)","difficulty":"hard","skill":"linear_functions","examSystem":"sat_math","createdVia":"compiler","subpattern":"lf.interpret_intercept.compare_scenarios/equation_vs_table_start","group":"lf.interpret_intercept.compare_scenarios","passage":"Two items, A and B, are tracked. For A, the audience is modeled by $A(t) = 3t + 62$, where t is in months. For B, the audience is 37 subscribers after 3 months and 55 subscribers after 5 months, and B also changes at a constant rate.","question":"How many more subscribers was A's starting audience than B's starting audience?","options":null,"correctIndex":null,"answers":["52"],"explanation":"(1) A 의 시작값은 y 절편 62 이다. (2) B 의 변화율은 (55 - 37) / (5 - 3) = 9 이다. (3) B 의 식을 y = 9t + b 로 놓는다. (4) 37 = 9·3 + b 에서 b = 10 이다. (5) 차는 62 - 10 = 52 이다. 따라서 정답은 52이다.","explanationEn":"(1) Read A's intercept. (2) Find B's rate. (3) Write B's form. (4) Solve for B's start. (5) Subtract. So the answer is 52.","figure":null,"statements":null,"evidenceTarget":null,"evidenceSpan":null,"answerRationale":null,"distractorErrorTypes":null,"renderCheck":{"ok":true,"renderer":"std-1","checkedAt":"2026-10-20T16:19:24.596Z","issues":[]},"publish":true,"quality":{"contract":{"ok":true,"issues":[]},"estimatedDifficulty":"hard","requestedDifficulty":"hard","difficultyReasons":["서로 다른 표현(식·표)으로 주어진 두 모델에서 절편을 각각 얻어 비교 — medium 은 한 모델의 절편 해석"],"distractors":[],"independentReview":{"pickedIndex":null,"pickedAnswer":null,"agrees":true,"confidence":"high","flags":[]},"needsReview":false,"needsReviewReasons":[],"calibrated":false,"reviewedAt":"1970-01-01T00:00:00.000Z","mockExamGeneration":{"difficultyStatus":"provisional_ai","source":"compiler_archetype","archetypeId":"lf.interpret_intercept.compare_scenarios","operator":"compare_scenarios","kind":"interpret_intercept","extraThinking":"서로 다른 표현(식·표)으로 주어진 두 모델에서 절편을 각각 얻어 비교 — medium 은 한 모델의 절편 해석","concepts":["y 절편의 의미(시작값)","표→직선의 식","두 값의 비교"],"steps":5,"mediumSteps":2,"seed":820000,"variant":"equation_vs_table_start","verification":{"method":"verification_js","verified":52,"correctOption":"52"},"runId":"sat-math-hard5","gid":"4cdac8e7-a82b-5179-a8dc-7332e6db175c","intendedSkill":"linear_functions","recipeId":"lf.interpret_intercept.compare_scenarios","recipeCheck":{"source":"compiler_archetype","compliance":{"met":3,"minMet":2,"of":3,"ok":true}},"hardBasis":"compiler_archetype","review":null}}},{"gid":"c440a88c-9bf4-5b34-a96d-6f9744f81de4","subject":"SAT Math","format":"mc","skillType":"Algebra (선형식·연립·부등식)","difficulty":"hard","skill":"linear_functions","examSystem":"sat_math","createdVia":"compiler","subpattern":"lf.evaluate.chain2/two_compositions","group":"lf.evaluate.chain2","passage":"Consider the pair of functions $g(x) = 4x + 1$ and $h(x) = 3x - 5$.","question":"What is the value of $g(h(4)) + h(g(1))$?","options":["39","29","15","19"],"correctIndex":0,"answers":null,"explanation":"(1) $h(4) = 3\\cdot 4 - 5 = 7$ 이다. (2) $g(h(4)) = g(7) = 29$ 이다. (3) $g(1) = 5$ 이다. (4) $h(g(1)) = h(5) = 10$ 이다. (5) 두 값을 더하면 39 이다. 따라서 정답은 39이다.","explanationEn":"(1) Evaluate the inner function. (2) Feed it into the outer function. (3) Evaluate the other inner function. (4) Feed it into the other outer function. (5) Combine. So the answer is 39.","figure":null,"statements":null,"evidenceTarget":null,"evidenceSpan":null,"answerRationale":null,"distractorErrorTypes":null,"renderCheck":{"ok":true,"renderer":"std-1","checkedAt":"2026-10-20T16:19:24.597Z","issues":[]},"publish":true,"quality":{"contract":{"ok":true,"issues":[]},"estimatedDifficulty":"hard","requestedDifficulty":"hard","difficultyReasons":["안쪽 함수값을 바깥 함수의 입력으로 넘기는 두 번의 합성과 순서(f∘g 와 g∘f)의 구분 — medium 은 함수값 하나 계산"],"distractors":[],"independentReview":{"pickedIndex":null,"pickedAnswer":null,"agrees":true,"confidence":"high","flags":[]},"needsReview":false,"needsReviewReasons":[],"calibrated":false,"reviewedAt":"1970-01-01T00:00:00.000Z","mockExamGeneration":{"difficultyStatus":"provisional_ai","source":"compiler_archetype","archetypeId":"lf.evaluate.chain2","operator":"chain2","kind":"evaluate","extraThinking":"안쪽 함수값을 바깥 함수의 입력으로 넘기는 두 번의 합성과 순서(f∘g 와 g∘f)의 구분 — medium 은 함수값 하나 계산","concepts":["함수값 계산","함수의 합성","합성 순서"],"steps":5,"mediumSteps":1,"seed":820001,"variant":"two_compositions","verification":{"method":"verification_js","verified":39,"correctOption":"39"},"runId":"sat-math-hard5","gid":"c440a88c-9bf4-5b34-a96d-6f9744f81de4","intendedSkill":"linear_functions","recipeId":"lf.evaluate.chain2","recipeCheck":{"source":"compiler_archetype","compliance":{"met":3,"minMet":2,"of":3,"ok":true}},"hardBasis":"compiler_archetype","review":null}}},{"gid":"5d826634-5026-5ee8-a2e6-289729e84b9f","subject":"SAT Math","format":"mc","skillType":"Algebra (선형식·연립·부등식)","difficulty":"hard","skill":"linear_functions","examSystem":"sat_math","createdVia":"compiler","subpattern":"lf.evaluate.compose_kind/restore_then_evaluate","group":"lf.evaluate.compose_kind","passage":"The linear function g satisfies $g(-5) = -5$ and $g(-2) = -8$.","question":"What does $g(5)$ equal?","options":["-1","15","-13","-15"],"correctIndex":3,"answers":null,"explanation":"(1) 기울기는 $(-8 - (-5)) / (-2 - (-5)) = -1$ 이다. (2) $g(x) = -1x + b$ 로 놓는다. (3) -5 를 대입하면 $-5 = -1\\cdot (-5) + b$ 이다. (4) b = -10 이므로 $g(x) = -x - 10$ 이다. (5) $g(5) = -1\\cdot 5 - 10 = -15$ 이다. 따라서 정답은 -15이다.","explanationEn":"(1) Find the slope. (2) Write the form. (3) Substitute a known point. (4) Solve for b. (5) Evaluate. So the answer is -15.","figure":null,"statements":null,"evidenceTarget":null,"evidenceSpan":null,"answerRationale":null,"distractorErrorTypes":null,"renderCheck":{"ok":true,"renderer":"std-1","checkedAt":"2026-10-20T16:19:24.597Z","issues":[]},"publish":true,"quality":{"contract":{"ok":true,"issues":[]},"estimatedDifficulty":"hard","requestedDifficulty":"hard","difficultyReasons":["함수값 두 개에서 직선의 식을 먼저 복원(기울기→절편)한 뒤 함수값을 계산 — medium 은 식이 주어진 함수값 계산"],"distractors":[],"independentReview":{"pickedIndex":null,"pickedAnswer":null,"agrees":true,"confidence":"high","flags":[]},"needsReview":false,"needsReviewReasons":[],"calibrated":false,"reviewedAt":"1970-01-01T00:00:00.000Z","mockExamGeneration":{"difficultyStatus":"provisional_ai","source":"compiler_archetype","archetypeId":"lf.evaluate.compose_kind","operator":"compose_kind","kind":"evaluate","extraThinking":"함수값 두 개에서 직선의 식을 먼저 복원(기울기→절편)한 뒤 함수값을 계산 — medium 은 식이 주어진 함수값 계산","concepts":["함수값 계산","두 점으로 직선의 식 구하기"],"steps":5,"mediumSteps":1,"seed":820000,"variant":"restore_then_evaluate","verification":{"method":"verification_js","verified":-15,"correctOption":"-15"},"runId":"sat-math-hard5","gid":"5d826634-5026-5ee8-a2e6-289729e84b9f","intendedSkill":"linear_functions","recipeId":"lf.evaluate.compose_kind","recipeCheck":{"source":"compiler_archetype","compliance":{"met":2,"minMet":2,"of":2,"ok":true}},"hardBasis":"compiler_archetype","review":null}}},{"gid":"ed2301ba-b880-5b9f-afc1-8cfee21bcb06","subject":"SAT Math","format":"spr","skillType":"Algebra (선형식·연립·부등식)","difficulty":"hard","skill":"linear_functions","examSystem":"sat_math","createdVia":"compiler","subpattern":"lf.evaluate.repr_shift/from_intercepts","group":"lf.evaluate.repr_shift","passage":"A linear function p has an x-intercept at $(6, 0)$ and a y-intercept at $(0, -6)$.","question":"What does the function output when the input is 1?","options":null,"correctIndex":null,"answers":["-5"],"explanation":"(1) x 절편은 점 (6, 0), y 절편은 점 (0, -6) 이다. (2) 기울기는 $(0 - (-6)) / (6 - 0) = 1$ 이다. (3) y 절편이 -6 이므로 $p(x) = x - 6$ 이다. (4) $p(1) = 1\\cdot 1 - 6$ 이다. (5) 계산하면 -5 이다. 따라서 정답은 -5이다.","explanationEn":"(1) Read the two intercept points. (2) Compute the slope. (3) Write the equation. (4) Substitute. (5) Evaluate. So the answer is -5.","figure":null,"statements":null,"evidenceTarget":null,"evidenceSpan":null,"answerRationale":null,"distractorErrorTypes":null,"renderCheck":{"ok":true,"renderer":"std-1","checkedAt":"2026-10-20T16:19:24.597Z","issues":[]},"publish":true,"quality":{"contract":{"ok":true,"issues":[]},"estimatedDifficulty":"hard","requestedDifficulty":"hard","difficultyReasons":["절편 서술(그래프의 좌표 정보)을 기울기와 식으로 번역한 뒤 함수값을 계산 — medium 은 식이 주어진 함수값 계산"],"distractors":[],"independentReview":{"pickedIndex":null,"pickedAnswer":null,"agrees":true,"confidence":"high","flags":[]},"needsReview":false,"needsReviewReasons":[],"calibrated":false,"reviewedAt":"1970-01-01T00:00:00.000Z","mockExamGeneration":{"difficultyStatus":"provisional_ai","source":"compiler_archetype","archetypeId":"lf.evaluate.repr_shift","operator":"repr_shift","kind":"evaluate","extraThinking":"절편 서술(그래프의 좌표 정보)을 기울기와 식으로 번역한 뒤 함수값을 계산 — medium 은 식이 주어진 함수값 계산","concepts":["절편으로 직선의 식 구하기","함수값 계산"],"steps":5,"mediumSteps":1,"seed":820000,"variant":"from_intercepts","verification":{"method":"verification_js","verified":-5,"correctOption":"-5"},"runId":"sat-math-hard5","gid":"ed2301ba-b880-5b9f-afc1-8cfee21bcb06","intendedSkill":"linear_functions","recipeId":"lf.evaluate.repr_shift","recipeCheck":{"source":"compiler_archetype","compliance":{"met":2,"minMet":2,"of":2,"ok":true}},"hardBasis":"compiler_archetype","review":null}}},{"gid":"917dca04-7758-5054-a982-8afd041c9e73","subject":"SAT Math","format":"mc","skillType":"Algebra (선형식·연립·부등식)","difficulty":"hard","skill":"linear_functions","examSystem":"sat_math","createdVia":"compiler","subpattern":"lf.evaluate.compare_scenarios/two_shops_difference","group":"lf.evaluate.compare_scenarios","passage":"At Shop A, a house call costs 40 dollars, and each hour adds 33 dollars. The price at Shop B is 15 dollars for a house call plus 18 dollars for every hour.","question":"For 9 hours, how many more dollars does Shop A charge than Shop B?","options":["40","337","160","-160"],"correctIndex":2,"answers":null,"explanation":"(1) Shop A 의 함수는 $A(t) = 33t + 40$ 이다. (2) Shop B 의 함수는 $B(t) = 18t + 15$ 이다. (3) $A(9) = 33\\cdot 9 + 40 = 337$ 이다. (4) $B(9) = 18\\cdot 9 + 15 = 177$ 이다. (5) 차는 337 - 177 = 160 이다. 따라서 정답은 160이다.","explanationEn":"(1) Model Shop A. (2) Model Shop B. (3) Evaluate A. (4) Evaluate B. (5) Subtract. So the answer is 160.","figure":null,"statements":null,"evidenceTarget":null,"evidenceSpan":null,"answerRationale":null,"distractorErrorTypes":null,"renderCheck":{"ok":true,"renderer":"std-1","checkedAt":"2026-10-20T16:19:24.597Z","issues":[]},"publish":true,"quality":{"contract":{"ok":true,"issues":[]},"estimatedDifficulty":"hard","requestedDifficulty":"hard","difficultyReasons":["두 상황을 각각 함수로 모델링한 뒤 같은 입력에서 값을 비교 — medium 은 주어진 하나의 함수값 계산"],"distractors":[],"independentReview":{"pickedIndex":null,"pickedAnswer":null,"agrees":true,"confidence":"high","flags":[]},"needsReview":false,"needsReviewReasons":[],"calibrated":false,"reviewedAt":"1970-01-01T00:00:00.000Z","mockExamGeneration":{"difficultyStatus":"provisional_ai","source":"compiler_archetype","archetypeId":"lf.evaluate.compare_scenarios","operator":"compare_scenarios","kind":"evaluate","extraThinking":"두 상황을 각각 함수로 모델링한 뒤 같은 입력에서 값을 비교 — medium 은 주어진 하나의 함수값 계산","concepts":["문장→일차함수","함수값 계산","두 값의 비교"],"steps":5,"mediumSteps":1,"seed":820001,"variant":"two_shops_difference","verification":{"method":"verification_js","verified":160,"correctOption":"160"},"runId":"sat-math-hard5","gid":"917dca04-7758-5054-a982-8afd041c9e73","intendedSkill":"linear_functions","recipeId":"lf.evaluate.compare_scenarios","recipeCheck":{"source":"compiler_archetype","compliance":{"met":3,"minMet":2,"of":3,"ok":true}},"hardBasis":"compiler_archetype","review":null}}},{"gid":"00bd78fd-b145-5b2f-a152-255ee2a3ceed","subject":"SAT Math","format":"mc","skillType":"Algebra (선형식·연립·부등식)","difficulty":"hard","skill":"linear_functions","examSystem":"sat_math","createdVia":"compiler","subpattern":"lf.find_x_for_value.inverse/equal_to_sum_of_values","group":"lf.find_x_for_value.inverse","passage":"Consider the function $f(x) = -3x - 3$. The equation $f(x) = f(4) + f(0)$ has exactly one solution.","question":"What is that value of x?","options":["-18","7","5","4"],"correctIndex":2,"answers":null,"explanation":"(1) $f(4) = -3\\cdot 4 - 3 = -15$ 이다. (2) $f(0) = -3$ 이다. (3) 합은 -18 이다. (4) $-3x - 3 = -18$ 로 놓는다. (5) 상수를 이항하면 $-3x = -15$ 이고 x = 5 이다. 따라서 정답은 5이다.","explanationEn":"(1) Evaluate f(p). (2) Evaluate f(q). (3) Add the two values. (4) Set f(x) equal to the sum. (5) Solve for x. So the answer is 5.","figure":null,"statements":null,"evidenceTarget":null,"evidenceSpan":null,"answerRationale":null,"distractorErrorTypes":null,"renderCheck":{"ok":true,"renderer":"std-1","checkedAt":"2026-10-20T16:19:24.598Z","issues":[]},"publish":true,"quality":{"contract":{"ok":true,"issues":[]},"estimatedDifficulty":"hard","requestedDifficulty":"hard","difficultyReasons":["정방향으로 만든 목표값을 다시 출력값으로 두고 입력을 역산 — medium 은 주어진 출력값에서 x 를 한 번 구함"],"distractors":[],"independentReview":{"pickedIndex":null,"pickedAnswer":null,"agrees":true,"confidence":"high","flags":[]},"needsReview":false,"needsReviewReasons":[],"calibrated":false,"reviewedAt":"1970-01-01T00:00:00.000Z","mockExamGeneration":{"difficultyStatus":"provisional_ai","source":"compiler_archetype","archetypeId":"lf.find_x_for_value.inverse","operator":"inverse","kind":"find_x_for_value","extraThinking":"정방향으로 만든 목표값을 다시 출력값으로 두고 입력을 역산 — medium 은 주어진 출력값에서 x 를 한 번 구함","concepts":["함수값 계산","출력값에서 입력 역산"],"steps":5,"mediumSteps":1,"seed":820000,"variant":"equal_to_sum_of_values","verification":{"method":"verification_js","verified":5,"correctOption":"5"},"runId":"sat-math-hard5","gid":"00bd78fd-b145-5b2f-a152-255ee2a3ceed","intendedSkill":"linear_functions","recipeId":"lf.find_x_for_value.inverse","recipeCheck":{"source":"compiler_archetype","compliance":{"met":2,"minMet":2,"of":2,"ok":true}},"hardBasis":"compiler_archetype","review":null}}},{"gid":"8ea760fe-293e-577e-afb1-3257e9d66979","subject":"SAT Math","format":"spr","skillType":"Algebra (선형식·연립·부등식)","difficulty":"hard","skill":"linear_functions","examSystem":"sat_math","createdVia":"compiler","subpattern":"lf.find_x_for_value.chain2/composite_equals_target","group":"lf.find_x_for_value.chain2","passage":"Look at the functions $r(x) = -2x - 6$ and $s(x) = -x - 3$.","question":"If $r(s(x)) = 14$, what is x?","options":null,"correctIndex":null,"answers":["7"],"explanation":"(1) $r(s(x)) = -2(-x - 3) - 6$ 이다. (2) 분배하면 $2x$ 이다. (3) $2x = 14$ 로 놓는다. (4) 상수를 이항하면 $2x = 14$ 이다. (5) 2 로 나누면 x = 7 이다. 따라서 정답은 7이다.","explanationEn":"(1) Substitute the inner function into the outer one. (2) Simplify the composite. (3) Set it equal to the target. (4) Isolate the x-term. (5) Solve. So the answer is 7.","figure":null,"statements":null,"evidenceTarget":null,"evidenceSpan":null,"answerRationale":null,"distractorErrorTypes":null,"renderCheck":{"ok":true,"renderer":"std-1","checkedAt":"2026-10-20T16:19:24.598Z","issues":[]},"publish":true,"quality":{"contract":{"ok":true,"issues":[]},"estimatedDifficulty":"hard","requestedDifficulty":"hard","difficultyReasons":["두 함수를 합성해 식을 정리(기울기 곱·상수 합성)한 뒤 방정식으로 푸는 2단계 — medium 은 한 함수에서 x 를 구함"],"distractors":[],"independentReview":{"pickedIndex":null,"pickedAnswer":null,"agrees":true,"confidence":"high","flags":[]},"needsReview":false,"needsReviewReasons":[],"calibrated":false,"reviewedAt":"1970-01-01T00:00:00.000Z","mockExamGeneration":{"difficultyStatus":"provisional_ai","source":"compiler_archetype","archetypeId":"lf.find_x_for_value.chain2","operator":"chain2","kind":"find_x_for_value","extraThinking":"두 함수를 합성해 식을 정리(기울기 곱·상수 합성)한 뒤 방정식으로 푸는 2단계 — medium 은 한 함수에서 x 를 구함","concepts":["함수의 합성","일차방정식","출력값에서 입력 역산"],"steps":5,"mediumSteps":1,"seed":820000,"variant":"composite_equals_target","verification":{"method":"verification_js","verified":7,"correctOption":"7"},"runId":"sat-math-hard5","gid":"8ea760fe-293e-577e-afb1-3257e9d66979","intendedSkill":"linear_functions","recipeId":"lf.find_x_for_value.chain2","recipeCheck":{"source":"compiler_archetype","compliance":{"met":3,"minMet":2,"of":3,"ok":true}},"hardBasis":"compiler_archetype","review":null}}},{"gid":"56f90c5b-9ef6-5ab9-a47c-87f58524e941","subject":"SAT Math","format":"mc","skillType":"Algebra (선형식·연립·부등식)","difficulty":"hard","skill":"linear_inequalities","examSystem":"sat_math","createdVia":"compiler","subpattern":"li.solve_one_var.param_condition/sign_of_coefficient","group":"li.solve_one_var.param_condition","passage":"Consider the inequality below, where c is a constant. Solving it gives the condition $x \\le 6$.\n\n$cx - 3 \\le 27$","question":"Find the value of c.","options":["-5","5","30","6"],"correctIndex":1,"answers":null,"explanation":"(1) cx 항만 남기도록 상수항을 이항하면 $cx \\le 30$ 이다. (2) 해집합은 $x \\le 6$ 로, 원래 부등호 at most 와 방향이 같다. (3) 방향이 같으므로 양수로 나눈 것이다: c > 0 이다. (4) c 로 나누면 경계값은 30/c 이다. (5) 경계값이 6 이므로 30/c = 6 이다. (6) c = 30/6 = 5 이고 부호 조건과 맞는다. 따라서 정답은 5이다.","explanationEn":"(1) Isolate the K-term. (2) Compare the direction of the solution set with the original sign. (3) A flipped sign means division by a negative number. (4) Divide to get the boundary value. (5) Equate the boundary with the given value. (6) Solve and check the sign condition. So the answer is 5.","figure":null,"statements":null,"evidenceTarget":null,"evidenceSpan":null,"answerRationale":null,"distractorErrorTypes":null,"renderCheck":{"ok":true,"renderer":"std-1","checkedAt":"2026-10-20T16:19:24.598Z","issues":[]},"publish":true,"quality":{"contract":{"ok":true,"issues":[]},"estimatedDifficulty":"hard","requestedDifficulty":"hard","difficultyReasons":["해집합의 방향이 원래 부등호와 다르면 음수로 나눴다는 뜻이므로 k<0 이라는 암묵 조건을 읽어 내고 경계값 방정식으로 k 를 결정 — medium 은 주어진 부등식을 푸는 정방향"],"distractors":[],"independentReview":{"pickedIndex":null,"pickedAnswer":null,"agrees":true,"confidence":"high","flags":[]},"needsReview":false,"needsReviewReasons":[],"calibrated":false,"reviewedAt":"1970-01-01T00:00:00.000Z","mockExamGeneration":{"difficultyStatus":"provisional_ai","source":"compiler_archetype","archetypeId":"li.solve_one_var.param_condition","operator":"param_condition","kind":"solve_one_var","extraThinking":"해집합의 방향이 원래 부등호와 다르면 음수로 나눴다는 뜻이므로 k<0 이라는 암묵 조건을 읽어 내고 경계값 방정식으로 k 를 결정 — medium 은 주어진 부등식을 푸는 정방향","concepts":["부등식의 해집합","음수로 나눌 때 방향 반전","경계값 방정식"],"steps":6,"mediumSteps":2,"seed":820000,"variant":"sign_of_coefficient","verification":{"method":"verification_js","verified":5,"correctOption":"5"},"runId":"sat-math-hard5","gid":"56f90c5b-9ef6-5ab9-a47c-87f58524e941","intendedSkill":"linear_inequalities","recipeId":"li.solve_one_var.param_condition","recipeCheck":{"source":"compiler_archetype","compliance":{"met":3,"minMet":2,"of":3,"ok":true}},"hardBasis":"compiler_archetype","review":null}}},{"gid":"f4bbe38a-423a-5b3e-a2f1-a1e5148779c0","subject":"SAT Math","format":"spr","skillType":"Algebra (선형식·연립·부등식)","difficulty":"hard","skill":"linear_inequalities","examSystem":"sat_math","createdVia":"compiler","subpattern":"li.solve_one_var.constraint_select/compound_least","group":"li.solve_one_var.constraint_select","passage":"Consider the two inequalities below.\n\n$2n + 6 \\le 4$\n$2n + 3 \\ge -13$","question":"Find the smallest integer solution of both inequalities.","options":null,"correctIndex":null,"answers":["-8"],"explanation":"(1) 첫 부등식을 풀면 $n \\ge -8$ (음수로 나누면 부등호 방향이 바뀐다). (2) 둘째 부등식을 풀면 $n \\le -1$. (3) 두 조건의 공통 구간(교집합)을 만든다. (4) 경계값이 포함되는지(≤, ≥ 인지 <, > 인지) 확인해 정수 후보를 정한다: -8, -7, -6, -5, -4, -3, -2, -1. (5) 가장 작은 정수는 -8 이다. 따라서 정답은 -8이다.","explanationEn":"(1) Solve the first inequality. (2) Solve the second inequality. (3) Intersect the two conditions. (4) List the integers allowed by the endpoints. (5) Answer the requested quantity. So the answer is -8.","figure":null,"statements":null,"evidenceTarget":null,"evidenceSpan":null,"answerRationale":null,"distractorErrorTypes":null,"renderCheck":{"ok":true,"renderer":"std-1","checkedAt":"2026-10-20T16:19:24.598Z","issues":[]},"publish":true,"quality":{"contract":{"ok":true,"issues":[]},"estimatedDifficulty":"hard","requestedDifficulty":"hard","difficultyReasons":["서로 다른 방향의 두 제약을 하나의 구간으로 합치고 경계 포함 여부를 따져 정수 후보를 걸러냄 — medium 은 부등식 하나의 해"],"distractors":[],"independentReview":{"pickedIndex":null,"pickedAnswer":null,"agrees":true,"confidence":"high","flags":[]},"needsReview":false,"needsReviewReasons":[],"calibrated":false,"reviewedAt":"1970-01-01T00:00:00.000Z","mockExamGeneration":{"difficultyStatus":"provisional_ai","source":"compiler_archetype","archetypeId":"li.solve_one_var.constraint_select","operator":"constraint_select","kind":"solve_one_var","extraThinking":"서로 다른 방향의 두 제약을 하나의 구간으로 합치고 경계 포함 여부를 따져 정수 후보를 걸러냄 — medium 은 부등식 하나의 해","concepts":["연립 부등식","구간의 교집합","정수 해 선택"],"steps":5,"mediumSteps":2,"seed":820000,"variant":"compound_least","verification":{"method":"verification_js","verified":-8,"correctOption":"-8"},"runId":"sat-math-hard5","gid":"f4bbe38a-423a-5b3e-a2f1-a1e5148779c0","intendedSkill":"linear_inequalities","recipeId":"li.solve_one_var.constraint_select","recipeCheck":{"source":"compiler_archetype","compliance":{"met":3,"minMet":2,"of":3,"ok":true}},"hardBasis":"compiler_archetype","review":null}}},{"gid":"084131e5-562b-5801-a82d-4636c47c2932","subject":"SAT Math","format":"mc","skillType":"Algebra (선형식·연립·부등식)","difficulty":"hard","skill":"linear_inequalities","examSystem":"sat_math","createdVia":"compiler","subpattern":"li.solve_one_var.chain2/greatest_k","group":"li.solve_one_var.chain2","passage":"Call the smallest integer solution of $4n + 2 > 10$ s. For an integer c, the value s satisfies $cn + 2 \\le 27$.","question":"What is the greatest possible value of c?","options":["3","7","9","8"],"correctIndex":3,"answers":null,"explanation":"(1) 첫 부등식을 풀면 $n > 2$ 이다. (2) 부등호가 '>' 이므로 경계값은 해가 아니다. 그보다 큰 가장 작은 정수는 3 이다. (3) 둘째 부등식에 n = 3 를 대입하면 $c\\cdot 3 + 2 \\le 27$ 이다. (4) 상수를 이항하면 $3c \\le 25$ 이다. (5) 양수 3 로 나누면 $c \\le 8.33$ 이다. (6) K 는 정수이므로 가장 큰 값은 8 이다. 따라서 정답은 8이다.","explanationEn":"(1) Solve the first inequality. (2) The boundary is excluded, so take the next integer. (3) Substitute the value. (4) Isolate the K-term. (5) Divide by the positive number. (6) Take the extreme integer. So the answer is 8.","figure":null,"statements":null,"evidenceTarget":null,"evidenceSpan":null,"answerRationale":null,"distractorErrorTypes":null,"renderCheck":{"ok":true,"renderer":"std-1","checkedAt":"2026-10-20T16:19:24.599Z","issues":[]},"publish":true,"quality":{"contract":{"ok":true,"issues":[]},"estimatedDifficulty":"hard","requestedDifficulty":"hard","difficultyReasons":["앞 부등식의 결과(최소 정수 해)가 뒤 부등식의 입력 값이 되는 2단계 연쇄 — medium 은 부등식 하나의 해"],"distractors":[],"independentReview":{"pickedIndex":null,"pickedAnswer":null,"agrees":true,"confidence":"high","flags":[]},"needsReview":false,"needsReviewReasons":[],"calibrated":false,"reviewedAt":"1970-01-01T00:00:00.000Z","mockExamGeneration":{"difficultyStatus":"provisional_ai","source":"compiler_archetype","archetypeId":"li.solve_one_var.chain2","operator":"chain2","kind":"solve_one_var","extraThinking":"앞 부등식의 결과(최소 정수 해)가 뒤 부등식의 입력 값이 되는 2단계 연쇄 — medium 은 부등식 하나의 해","concepts":["부등식 풀이","최소 정수 해","대입 후 매개변수 부등식"],"steps":6,"mediumSteps":2,"seed":820000,"variant":"greatest_k","verification":{"method":"verification_js","verified":8,"correctOption":"8"},"runId":"sat-math-hard5","gid":"084131e5-562b-5801-a82d-4636c47c2932","intendedSkill":"linear_inequalities","recipeId":"li.solve_one_var.chain2","recipeCheck":{"source":"compiler_archetype","compliance":{"met":3,"minMet":2,"of":3,"ok":true}},"hardBasis":"compiler_archetype","review":null}}},{"gid":"3894be18-adfb-5019-a27b-a163e4e85481","subject":"SAT Math","format":"spr","skillType":"Algebra (선형식·연립·부등식)","difficulty":"hard","skill":"linear_inequalities","examSystem":"sat_math","createdVia":"compiler","subpattern":"li.point_in_solution.inverse/unknown_constant_count","group":"li.point_in_solution.inverse","passage":"Let b be an integer in the inequality below. It is known that $(-2, 7)$ lies in the solution set.\n\n$y < -4x + b$","question":"For how many integers b with $-5 \\le b \\le 5$ is this possible?","options":null,"correctIndex":null,"answers":["6"],"explanation":"(1) 점 (-2, 7) 를 대입하면 $7 < -4\\cdot (-2) + b$ 이다. (2) 정리하면 $7 < 8 + b$ 이다. (3) b 에 대해 풀면 $b > -1$ 이다. (4) 경계값 -1 가 제외된다. (5) 정수 범위 -5 이상 5 이하와 겹치는 정수를 센다. (6) 가능한 정수 b 는 6개이다. 따라서 정답은 6이다.","explanationEn":"(1) Substitute the point. (2) Simplify. (3) Solve for b. (4) Decide whether the endpoint is included. (5) Intersect with the allowed range. (6) Count. So the answer is 6.","figure":null,"statements":null,"evidenceTarget":null,"evidenceSpan":null,"answerRationale":null,"distractorErrorTypes":null,"renderCheck":{"ok":true,"renderer":"std-1","checkedAt":"2026-10-20T16:19:24.599Z","issues":[]},"publish":true,"quality":{"contract":{"ok":true,"issues":[]},"estimatedDifficulty":"hard","requestedDifficulty":"hard","difficultyReasons":["점을 대입한 결과를 미지 상수에 대한 부등식으로 거꾸로 풀고 경계 포함 여부와 범위 제한을 함께 처리 — medium 은 점이 해인지 판정하는 정방향"],"distractors":[],"independentReview":{"pickedIndex":null,"pickedAnswer":null,"agrees":true,"confidence":"high","flags":[]},"needsReview":false,"needsReviewReasons":[],"calibrated":false,"reviewedAt":"1970-01-01T00:00:00.000Z","mockExamGeneration":{"difficultyStatus":"provisional_ai","source":"compiler_archetype","archetypeId":"li.point_in_solution.inverse","operator":"inverse","kind":"point_in_solution","extraThinking":"점을 대입한 결과를 미지 상수에 대한 부등식으로 거꾸로 풀고 경계 포함 여부와 범위 제한을 함께 처리 — medium 은 점이 해인지 판정하는 정방향","concepts":["점의 대입","미지 상수에 대한 부등식","정수 개수 세기"],"steps":6,"mediumSteps":2,"seed":820000,"variant":"unknown_constant_count","verification":{"method":"verification_js","verified":6,"correctOption":"6"},"runId":"sat-math-hard5","gid":"3894be18-adfb-5019-a27b-a163e4e85481","intendedSkill":"linear_inequalities","recipeId":"li.point_in_solution.inverse","recipeCheck":{"source":"compiler_archetype","compliance":{"met":3,"minMet":2,"of":3,"ok":true}},"hardBasis":"compiler_archetype","review":null}}},{"gid":"34232fb7-f8a9-5883-ae65-dd626138840b","subject":"SAT Math","format":"mc","skillType":"Algebra (선형식·연립·부등식)","difficulty":"hard","skill":"linear_inequalities","examSystem":"sat_math","createdVia":"compiler","subpattern":"li.point_in_solution.constraint_select/lattice_between_lines","group":"li.point_in_solution.constraint_select","passage":"A point (x, y) must satisfy both inequalities below.\n\n$y > -2x - 1$\n$y \\le -x + 8$\n\nOnly points whose coordinates are positive integers and whose x-coordinate is at most 5 are counted.","question":"How many such points are solutions to both inequalities?","options":["26","60","25","20"],"correctIndex":2,"answers":null,"explanation":"(1) 두 부등식을 각 x 에 대해 y 의 범위로 읽는다. (2) x = 1: y 는 -3 보다 커야 하고 7 보다 작거나 같아야 하며 양의 정수이므로 7개이다. (3) x = 2: y 는 -5 보다 커야 하고 6 보다 작거나 같아야 하며 양의 정수이므로 6개이다. (4) x = 3: y 는 -7 보다 커야 하고 5 보다 작거나 같아야 하며 양의 정수이므로 5개이다. (5) x = 4: y 는 -9 보다 커야 하고 4 보다 작거나 같아야 하며 양의 정수이므로 4개이다. (6) x = 5: y 는 -11 보다 커야 하고 3 보다 작거나 같아야 하며 양의 정수이므로 3개이다. (7) 열별 개수를 모두 더하면 7 + 6 + 5 + 4 + 3 = 25 이다. 따라서 정답은 25이다.","explanationEn":"(1) Read both as bounds on y for each x. (2) For x = 1 count the allowed y. (3) For x = 2 count the allowed y. (4) For x = 3 count the allowed y. (5) For x = 4 count the allowed y. (6) For x = 5 count the allowed y. (7) Add the counts. So the answer is 25.","figure":null,"statements":null,"evidenceTarget":null,"evidenceSpan":null,"answerRationale":null,"distractorErrorTypes":null,"renderCheck":{"ok":true,"renderer":"std-1","checkedAt":"2026-10-20T16:19:24.599Z","issues":[]},"publish":true,"quality":{"contract":{"ok":true,"issues":[]},"estimatedDifficulty":"hard","requestedDifficulty":"hard","difficultyReasons":["각 x 마다 y 의 허용 구간(포함 여부 포함)을 따로 구해 격자점을 선택·합산 — medium 은 점 하나가 해인지 판정"],"distractors":[],"independentReview":{"pickedIndex":null,"pickedAnswer":null,"agrees":true,"confidence":"high","flags":[]},"needsReview":false,"needsReviewReasons":[],"calibrated":false,"reviewedAt":"1970-01-01T00:00:00.000Z","mockExamGeneration":{"difficultyStatus":"provisional_ai","source":"compiler_archetype","archetypeId":"li.point_in_solution.constraint_select","operator":"constraint_select","kind":"point_in_solution","extraThinking":"각 x 마다 y 의 허용 구간(포함 여부 포함)을 따로 구해 격자점을 선택·합산 — medium 은 점 하나가 해인지 판정","concepts":["연립 부등식의 영역","격자점 세기","경계 포함 여부"],"steps":7,"mediumSteps":2,"seed":820000,"variant":"lattice_between_lines","verification":{"method":"verification_js","verified":25,"correctOption":"25"},"runId":"sat-math-hard5","gid":"34232fb7-f8a9-5883-ae65-dd626138840b","intendedSkill":"linear_inequalities","recipeId":"li.point_in_solution.constraint_select","recipeCheck":{"source":"compiler_archetype","compliance":{"met":3,"minMet":2,"of":3,"ok":true}},"hardBasis":"compiler_archetype","review":null}}},{"gid":"d279f433-6845-524e-af24-642e0c12020c","subject":"SAT Math","format":"mc","skillType":"Algebra (선형식·연립·부등식)","difficulty":"hard","skill":"linear_inequalities","examSystem":"sat_math","createdVia":"compiler","subpattern":"li.point_in_solution.repr_shift/revenue_goal_round_up","group":"li.point_in_solution.repr_shift","passage":"At a charity sale, each hardcover book costs 15 dollars and each paperback book costs 9 dollars. Total sales of at least 390 dollars are needed. 12 hardcover books are already sold.","question":"What is the least number of paperback books that must also be sold to reach the goal?","options":["43","23","25","24"],"correctIndex":3,"answers":null,"explanation":"(1) hardcover book 수를 x, paperback book 수를 y 라 하면 수입은 $15x + 9y$ 이다. (2) 목표는 $15x + 9y \\ge 390$ 이다. (3) x = 12 를 대입하면 $9y \\ge 210$ 이다. (4) 9 로 나누면 $y \\ge 23.33$ 이다. (5) 판매 수는 정수이므로 올림한다. (6) 최소 판매 수는 24 이다. 따라서 정답은 24이다.","explanationEn":"(1) Model total revenue. (2) Write the goal as an inequality. (3) Substitute the known count. (4) Divide. (5) Counts are whole numbers, so round up. (6) Answer. So the answer is 24.","figure":null,"statements":null,"evidenceTarget":null,"evidenceSpan":null,"answerRationale":null,"distractorErrorTypes":null,"renderCheck":{"ok":true,"renderer":"std-1","checkedAt":"2026-10-20T16:19:24.599Z","issues":[]},"publish":true,"quality":{"contract":{"ok":true,"issues":[]},"estimatedDifficulty":"hard","requestedDifficulty":"hard","difficultyReasons":["문장을 두 변수 부등식으로 모델링하고 한 변수를 대입한 뒤 정수 조건(올림)을 적용 — medium 은 주어진 부등식에 점을 대입해 판정"],"distractors":[],"independentReview":{"pickedIndex":null,"pickedAnswer":null,"agrees":true,"confidence":"high","flags":[]},"needsReview":false,"needsReviewReasons":[],"calibrated":false,"reviewedAt":"1970-01-01T00:00:00.000Z","mockExamGeneration":{"difficultyStatus":"provisional_ai","source":"compiler_archetype","archetypeId":"li.point_in_solution.repr_shift","operator":"repr_shift","kind":"point_in_solution","extraThinking":"문장을 두 변수 부등식으로 모델링하고 한 변수를 대입한 뒤 정수 조건(올림)을 적용 — medium 은 주어진 부등식에 점을 대입해 판정","concepts":["문장→두 변수 부등식","대입","정수 조건과 올림"],"steps":6,"mediumSteps":2,"seed":820000,"variant":"revenue_goal_round_up","verification":{"method":"verification_js","verified":24,"correctOption":"24"},"runId":"sat-math-hard5","gid":"d279f433-6845-524e-af24-642e0c12020c","intendedSkill":"linear_inequalities","recipeId":"li.point_in_solution.repr_shift","recipeCheck":{"source":"compiler_archetype","compliance":{"met":3,"minMet":2,"of":3,"ok":true}},"hardBasis":"compiler_archetype","review":null}}},{"gid":"0005f76b-d9d2-5253-afc1-67954539e085","subject":"SAT Math","format":"mc","skillType":"Algebra (선형식·연립·부등식)","difficulty":"hard","skill":"linear_inequalities","examSystem":"sat_math","createdVia":"compiler","subpattern":"li.point_in_solution.compare_scenarios/plan_crossover","group":"li.point_in_solution.compare_scenarios","passage":"A gym offers two plans. Plan A has a joining fee of 65 dollars and charges 14 dollars per visit. Under Plan B, a joining fee of 161 dollars is paid and each visit costs 8 dollars. Only whole numbers of visits can be purchased.","question":"Beginning with how many visits does Plan B cost strictly less than Plan A?","options":["18","21","17","16"],"correctIndex":2,"answers":null,"explanation":"(1) Plan A 의 비용은 $65 + 14n$ 이다. (2) Plan B 의 비용은 $161 + 8n$ 이다. (3) B 가 더 싸려면 $161 + 8n < 65 + 14n$ 이어야 한다. (4) n 항을 모으면 $96 < 6n$ 이다. (5) $n > 16$ 이다. (6) 경계 (정수이므로 포함되지 않는다) 다음 정수는 17 이다. 따라서 정답은 17이다.","explanationEn":"(1) Write Plan A's cost. (2) Write Plan B's cost. (3) Write the comparison. (4) Collect n terms. (5) Divide. (6) Take the next whole number. So the answer is 17.","figure":null,"statements":null,"evidenceTarget":null,"evidenceSpan":null,"answerRationale":null,"distractorErrorTypes":null,"renderCheck":{"ok":true,"renderer":"std-1","checkedAt":"2026-10-20T16:19:24.599Z","issues":[]},"publish":true,"quality":{"contract":{"ok":true,"issues":[]},"estimatedDifficulty":"hard","requestedDifficulty":"hard","difficultyReasons":["서로 다른 고정비와 단위비용의 두 비용식을 비교하는 부등식을 세우고 임계점 직후의 정수를 선택 — medium 은 주어진 하나의 식에 대입"],"distractors":[],"independentReview":{"pickedIndex":null,"pickedAnswer":null,"agrees":true,"confidence":"high","flags":[]},"needsReview":false,"needsReviewReasons":[],"calibrated":false,"reviewedAt":"1970-01-01T00:00:00.000Z","mockExamGeneration":{"difficultyStatus":"provisional_ai","source":"compiler_archetype","archetypeId":"li.point_in_solution.compare_scenarios","operator":"compare_scenarios","kind":"point_in_solution","extraThinking":"서로 다른 고정비와 단위비용의 두 비용식을 비교하는 부등식을 세우고 임계점 직후의 정수를 선택 — medium 은 주어진 하나의 식에 대입","concepts":["두 비용식 모델링","비교 부등식","임계점과 정수 선택"],"steps":6,"mediumSteps":2,"seed":820000,"variant":"plan_crossover","verification":{"method":"verification_js","verified":17,"correctOption":"17"},"runId":"sat-math-hard5","gid":"0005f76b-d9d2-5253-afc1-67954539e085","intendedSkill":"linear_inequalities","recipeId":"li.point_in_solution.compare_scenarios","recipeCheck":{"source":"compiler_archetype","compliance":{"met":3,"minMet":2,"of":3,"ok":true}},"hardBasis":"compiler_archetype","review":null}}},{"gid":"b2ea96b7-6706-5476-a8b3-8b9edb73236f","subject":"SAT Math","format":"spr","skillType":"Algebra (선형식·연립·부등식)","difficulty":"hard","skill":"linear_inequalities","examSystem":"sat_math","createdVia":"compiler","subpattern":"li.table_verification.repr_shift/sentence_to_inequality","group":"li.table_verification.repr_shift","passage":"A statement about a point (x, y) is given. The y-value is less than 6 less than 3 times the x-value. The pairs to check are $(-3, -16)$, $(-2, -11)$, $(0, -6)$, $(1, -5)$, $(3, 3)$, and $(4, 4)$.","question":"How many of the ordered pairs satisfy the statement?","options":null,"correctIndex":null,"answers":["3"],"explanation":"(1) 문장을 식으로 번역한다: $y < 3x - 6$. (2) (-3, -16): 우변 -15, 좌변 -16 → 참. (3) (-2, -11): 우변 -12, 좌변 -11 → 거짓. (4) (0, -6): 우변 -6, 좌변 -6 → 거짓. (5) (1, -5): 우변 -3, 좌변 -5 → 참. (6) (3, 3): 우변 3, 좌변 3 → 거짓. (7) (4, 4): 우변 6, 좌변 4 → 참. (8) 참인 쌍은 3개이다. 따라서 정답은 3이다.","explanationEn":"(1) Translate the sentence. (2) Test the pair (-3, -16). (3) Test the pair (-2, -11). (4) Test the pair (0, -6). (5) Test the pair (1, -5). (6) Test the pair (3, 3). (7) Test the pair (4, 4). (8) Count the true cases. So the answer is 3.","figure":null,"statements":null,"evidenceTarget":null,"evidenceSpan":null,"answerRationale":null,"distractorErrorTypes":null,"renderCheck":{"ok":true,"renderer":"std-1","checkedAt":"2026-10-20T16:19:24.599Z","issues":[]},"publish":true,"quality":{"contract":{"ok":true,"issues":[]},"estimatedDifficulty":"hard","requestedDifficulty":"hard","difficultyReasons":["문장 서술을 부등식 기호와 방향으로 정확히 번역(m 배보다 b 큰 → mx + b)하고 경계 위 점을 포함 여부로 판정 — medium 은 식이 주어진 상태에서 검증"],"distractors":[],"independentReview":{"pickedIndex":null,"pickedAnswer":null,"agrees":true,"confidence":"high","flags":[]},"needsReview":false,"needsReviewReasons":[],"calibrated":false,"reviewedAt":"1970-01-01T00:00:00.000Z","mockExamGeneration":{"difficultyStatus":"provisional_ai","source":"compiler_archetype","archetypeId":"li.table_verification.repr_shift","operator":"repr_shift","kind":"table_verification","extraThinking":"문장 서술을 부등식 기호와 방향으로 정확히 번역(m 배보다 b 큰 → mx + b)하고 경계 위 점을 포함 여부로 판정 — medium 은 식이 주어진 상태에서 검증","concepts":["문장→부등식 번역","순서쌍 대입 검증","경계 포함 여부"],"steps":8,"mediumSteps":4,"seed":820000,"variant":"sentence_to_inequality","verification":{"method":"verification_js","verified":3,"correctOption":"3"},"runId":"sat-math-hard5","gid":"b2ea96b7-6706-5476-a8b3-8b9edb73236f","intendedSkill":"linear_inequalities","recipeId":"li.table_verification.repr_shift","recipeCheck":{"source":"compiler_archetype","compliance":{"met":3,"minMet":2,"of":3,"ok":true}},"hardBasis":"compiler_archetype","review":null}}},{"gid":"8d1e5fba-7145-5d71-a7eb-9def872de511","subject":"SAT Math","format":"mc","skillType":"Algebra (선형식·연립·부등식)","difficulty":"hard","skill":"linear_inequalities","examSystem":"sat_math","createdVia":"compiler","subpattern":"li.table_verification.inverse/rebuild_from_boundary_points","group":"li.table_verification.inverse","passage":"In the xy-plane, the points that satisfy a certain linear inequality form the region above its boundary line, and the boundary line belongs to the solution set. The line that bounds the region passes through $(0, -6)$ and $(3, -11)$.","question":"What is the largest integer $y$ for which the point $(5, y)$ is not a solution?","options":["-15","-9","-14","-16"],"correctIndex":0,"answers":null,"explanation":"(1) 두 점으로 기울기를 구하면 -5/3 이다. (2) 경계선은 점 (0, -6) 을 지나므로 $y = -6 + \\frac{-5}{3}(x - 0)$ 이다. (3) 영역이 위쪽이고 경계가 포함되므로 해 영역은 y 가 경계선보다 큰 점들이다(경계 포함). (4) x = 5 에서 경계선의 y 값은 -14.333 이다. (5) 해가 아닌 y 는 경계값 이하에서 경계값 자체는 해이므로 제외이다. (6) 가장 큰 정수는 -15 이다. 따라서 정답은 -15이다.","explanationEn":"(1) Find the slope from the two points. (2) Write the boundary line. (3) Restore the solution region. (4) Evaluate the boundary at x = p. (5) Find the non-solutions. (6) Choose the extreme integer. So the answer is -15.","figure":null,"statements":null,"evidenceTarget":null,"evidenceSpan":null,"answerRationale":null,"distractorErrorTypes":null,"renderCheck":{"ok":true,"renderer":"std-1","checkedAt":"2026-10-20T16:19:24.600Z","issues":[]},"publish":true,"quality":{"contract":{"ok":true,"issues":[]},"estimatedDifficulty":"hard","requestedDifficulty":"hard","difficultyReasons":["두 점에서 기울기와 직선을 역으로 복원해 부등식 영역을 재구성하고, 경계값이 정수가 아닐 때 해가 아닌 정수의 끝값을 선택 — medium 은 주어진 부등식으로 검증"],"distractors":[],"independentReview":{"pickedIndex":null,"pickedAnswer":null,"agrees":true,"confidence":"high","flags":[]},"needsReview":false,"needsReviewReasons":[],"calibrated":false,"reviewedAt":"1970-01-01T00:00:00.000Z","mockExamGeneration":{"difficultyStatus":"provisional_ai","source":"compiler_archetype","archetypeId":"li.table_verification.inverse","operator":"inverse","kind":"table_verification","extraThinking":"두 점에서 기울기와 직선을 역으로 복원해 부등식 영역을 재구성하고, 경계값이 정수가 아닐 때 해가 아닌 정수의 끝값을 선택 — medium 은 주어진 부등식으로 검증","concepts":["두 점으로 직선 복원","부등식 영역 해석","정수 끝값"],"steps":6,"mediumSteps":4,"seed":820000,"variant":"rebuild_from_boundary_points","verification":{"method":"verification_js","verified":-15,"correctOption":"-15"},"runId":"sat-math-hard5","gid":"8d1e5fba-7145-5d71-a7eb-9def872de511","intendedSkill":"linear_inequalities","recipeId":"li.table_verification.inverse","recipeCheck":{"source":"compiler_archetype","compliance":{"met":3,"minMet":2,"of":3,"ok":true}},"hardBasis":"compiler_archetype","review":null}}},{"gid":"9e86409b-74b1-5d11-a5b0-c3ee61e2e7c5","subject":"SAT Math","format":"spr","skillType":"Algebra (선형식·연립·부등식)","difficulty":"hard","skill":"linear_inequalities","examSystem":"sat_math","createdVia":"compiler","subpattern":"li.table_verification.compare_scenarios/first_but_not_second","group":"li.table_verification.compare_scenarios","passage":"Two inequalities are given below.\n\n$y \\ge -x - 3$\n$y < -x - 5$\n\nThe ordered pairs are $(-2, -3)$, $(-1, -1)$, $(1, -5)$, $(2, -8)$, $(3, -6)$, and $(4, -9)$.","question":"How many of the pairs are solutions to the first inequality and not solutions to the second?","options":null,"correctIndex":null,"answers":["2"],"explanation":"(1) (-2, -3): 첫째 거짓(-3 vs -1), 둘째 거짓(-3 vs -3). (2) (-1, -1): 첫째 참(-1 vs -2), 둘째 거짓(-1 vs -4). (3) (1, -5): 첫째 거짓(-5 vs -4), 둘째 거짓(-5 vs -6). (4) (2, -8): 첫째 거짓(-8 vs -5), 둘째 참(-8 vs -7). (5) (3, -6): 첫째 참(-6 vs -6), 둘째 거짓(-6 vs -8). (6) (4, -9): 첫째 거짓(-9 vs -7), 둘째 거짓(-9 vs -9). (7) 첫째만 참이고 둘째는 거짓인 쌍은 2개이다. 따라서 정답은 2이다.","explanationEn":"(1) Test the pair (-2, -3) in both. (2) Test the pair (-1, -1) in both. (3) Test the pair (1, -5) in both. (4) Test the pair (2, -8) in both. (5) Test the pair (3, -6) in both. (6) Test the pair (4, -9) in both. (7) Count the pairs that are true for the first only. So the answer is 2.","figure":null,"statements":null,"evidenceTarget":null,"evidenceSpan":null,"answerRationale":null,"distractorErrorTypes":null,"renderCheck":{"ok":true,"renderer":"std-1","checkedAt":"2026-10-20T16:19:24.600Z","issues":[]},"publish":true,"quality":{"contract":{"ok":true,"issues":[]},"estimatedDifficulty":"hard","requestedDifficulty":"hard","difficultyReasons":["두 조건을 각 점에 독립적으로 적용한 뒤 '하나는 참, 다른 하나는 거짓'이라는 논리 조합을 선택 — medium 은 하나의 부등식 검증"],"distractors":[],"independentReview":{"pickedIndex":null,"pickedAnswer":null,"agrees":true,"confidence":"high","flags":[]},"needsReview":false,"needsReviewReasons":[],"calibrated":false,"reviewedAt":"1970-01-01T00:00:00.000Z","mockExamGeneration":{"difficultyStatus":"provisional_ai","source":"compiler_archetype","archetypeId":"li.table_verification.compare_scenarios","operator":"compare_scenarios","kind":"table_verification","extraThinking":"두 조건을 각 점에 독립적으로 적용한 뒤 '하나는 참, 다른 하나는 거짓'이라는 논리 조합을 선택 — medium 은 하나의 부등식 검증","concepts":["점 대입 검증","두 조건의 논리 조합","경계 포함 여부"],"steps":7,"mediumSteps":4,"seed":820000,"variant":"first_but_not_second","verification":{"method":"verification_js","verified":2,"correctOption":"2"},"runId":"sat-math-hard5","gid":"9e86409b-74b1-5d11-a5b0-c3ee61e2e7c5","intendedSkill":"linear_inequalities","recipeId":"li.table_verification.compare_scenarios","recipeCheck":{"source":"compiler_archetype","compliance":{"met":3,"minMet":2,"of":3,"ok":true}},"hardBasis":"compiler_archetype","review":null}}},{"gid":"15a18c2f-bbae-5567-ac7b-4b1fc356eb72","subject":"SAT Math","format":"mc","skillType":"Algebra (선형식·연립·부등식)","difficulty":"hard","skill":"linear_inequalities","examSystem":"sat_math","createdVia":"compiler","subpattern":"lib.ineq_applications.constraint_select/abs_count_integers","group":"lib.ineq_applications.constraint_select","passage":"Students in a review session were given the description below. Consider the inequality $|2x - 9| < 13$, where x is an integer. Every number given here is exact and comes from the official records.","question":"For how many integers x is the inequality true?","options":["11","24","12","13"],"correctIndex":2,"answers":null,"explanation":"(1) 절댓값 부등식은 −13 < 2x − 9 < 13 로 쓸 수 있다. (2) 각 변에 9 를 더하면 -4 < 2x < 22 이다. (3) 2 로 나누면 -2.00 < x < 11.00 이다. (4) 양 끝은 포함되지 않는다. (5) 그 사이의 정수는 12 개이다. 따라서 정답은 12이다.","explanationEn":"(1) Rewrite the absolute value inequality as a compound inequality. (2) Add the constant to all parts. (3) Divide by the coefficient. (4) Endpoints are excluded. (5) Count the integers. So the answer is 12.","figure":null,"statements":null,"evidenceTarget":null,"evidenceSpan":null,"answerRationale":null,"distractorErrorTypes":null,"renderCheck":{"ok":true,"renderer":"std-1","checkedAt":"2026-10-20T16:19:24.600Z","issues":[]},"publish":true,"quality":{"contract":{"ok":true,"issues":[]},"estimatedDifficulty":"hard","requestedDifficulty":"hard","difficultyReasons":["제약을 스스로 부등식으로 세우고 경계 포함 여부와 정수 조건으로 해를 골라야 함 — medium 은 주어진 일차부등식 하나의 해"],"distractors":[],"independentReview":{"pickedIndex":null,"pickedAnswer":null,"agrees":true,"confidence":"high","flags":[]},"needsReview":false,"needsReviewReasons":[],"calibrated":false,"reviewedAt":"1970-01-01T00:00:00.000Z","mockExamGeneration":{"difficultyStatus":"provisional_ai","source":"compiler_archetype","archetypeId":"lib.ineq_applications.constraint_select","operator":"constraint_select","kind":"ineq_applications","extraThinking":"제약을 스스로 부등식으로 세우고 경계 포함 여부와 정수 조건으로 해를 골라야 함 — medium 은 주어진 일차부등식 하나의 해","concepts":["부등식 모델링","경계 포함 여부","정수 해 선택"],"steps":5,"mediumSteps":2,"seed":820000,"variant":"abs_count_integers","verification":{"method":"verification_js","verified":12,"correctOption":"12"},"runId":"sat-math-hard5","gid":"15a18c2f-bbae-5567-ac7b-4b1fc356eb72","intendedSkill":"linear_inequalities","recipeId":"lib.ineq_applications.constraint_select","recipeCheck":{"source":"compiler_archetype","compliance":{"met":3,"minMet":2,"of":3,"ok":true}},"hardBasis":"compiler_archetype","review":null}}},{"gid":"baf7ec7d-bf2b-5325-a440-207c9106d7a8","subject":"SAT Math","format":"spr","skillType":"Algebra (선형식·연립·부등식)","difficulty":"hard","skill":"linear_inequalities","examSystem":"sat_math","createdVia":"compiler","subpattern":"lib.ineq_applications.inverse/least_k_for_all_x_above","group":"lib.ineq_applications.inverse","passage":"This scenario was chosen for a class on problem solving. The positive integer k is chosen so that $kx + 6 \\ge 89$ is true for every real number x with x ≥ 3. A copy of the facts was kept on file for future reference.","question":"What is the smallest integer that k can be?","options":null,"correctIndex":null,"answers":["28"],"explanation":"(1) k 가 양수이므로 kx + c 는 x 가 커질수록 커진다. (2) 따라서 가장 작은 x = 3 에서 성립하면 충분하다. (3) 3k + 6 ≥ 89 이다. (4) k ≥ 27.666666666666668 = 27.67 이다. (5) 가장 작은 정수는 28 이다. 따라서 정답은 28이다.","explanationEn":"(1) With k positive the expression increases in x. (2) Check the smallest x. (3) Substitute. (4) Solve. (5) Round up. So the answer is 28.","figure":null,"statements":null,"evidenceTarget":null,"evidenceSpan":null,"answerRationale":null,"distractorErrorTypes":null,"renderCheck":{"ok":true,"renderer":"std-1","checkedAt":"2026-10-20T16:19:24.600Z","issues":[]},"publish":true,"quality":{"contract":{"ok":true,"issues":[]},"estimatedDifficulty":"hard","requestedDifficulty":"hard","difficultyReasons":["해의 조건에서 상수나 계수의 범위를 역으로 세워 극값을 고르는 역문제 — medium 은 상수를 알고 해를 구하는 정방향"],"distractors":[],"independentReview":{"pickedIndex":null,"pickedAnswer":null,"agrees":true,"confidence":"high","flags":[]},"needsReview":false,"needsReviewReasons":[],"calibrated":false,"reviewedAt":"1970-01-01T00:00:00.000Z","mockExamGeneration":{"difficultyStatus":"provisional_ai","source":"compiler_archetype","archetypeId":"lib.ineq_applications.inverse","operator":"inverse","kind":"ineq_applications","extraThinking":"해의 조건에서 상수나 계수의 범위를 역으로 세워 극값을 고르는 역문제 — medium 은 상수를 알고 해를 구하는 정방향","concepts":["해로부터 매개변수 역산","부등식의 경계","정수 극값"],"steps":5,"mediumSteps":2,"seed":820000,"variant":"least_k_for_all_x_above","verification":{"method":"verification_js","verified":28,"correctOption":"28"},"runId":"sat-math-hard5","gid":"baf7ec7d-bf2b-5325-a440-207c9106d7a8","intendedSkill":"linear_inequalities","recipeId":"lib.ineq_applications.inverse","recipeCheck":{"source":"compiler_archetype","compliance":{"met":3,"minMet":2,"of":3,"ok":true}},"hardBasis":"compiler_archetype","review":null}}},{"gid":"2f899045-1778-5948-a2c0-d5abf2ab6e3f","subject":"SAT Math","format":"mc","skillType":"Algebra (선형식·연립·부등식)","difficulty":"hard","skill":"linear_inequalities","examSystem":"sat_math","createdVia":"compiler","subpattern":"lib.ineq_applications.chain2/min_trips_by_capacity","group":"lib.ineq_applications.chain2","passage":"A tutor shared the scenario below with a small study group. A lift can raise at most 1000 pounds per trip. A crew must move 70 identical sandbags up to a rooftop, and each one weighs 65 pounds. A copy of the facts was kept on file for future reference.","question":"At least how many trips must the lift make?","options":["5","4","70","6"],"correctIndex":0,"answers":null,"explanation":"(1) 한 번에 65x ≤ 1000 이므로 x ≤ 15.38 이다. (2) 정수이므로 한 번에 최대 15 개를 옮긴다. (3) 70 개를 옮기려면 70 ÷ 15 = 4.67 번이 필요하다. (4) 횟수는 정수여야 하므로 올림한다. (5) 5 번이다. 따라서 정답은 5이다.","explanationEn":"(1) Inequality for the load of one trip. (2) Round down per trip. (3) Trips needed. (4) Round up to whole trips. (5) Answer. So the answer is 5.","figure":null,"statements":null,"evidenceTarget":null,"evidenceSpan":null,"answerRationale":null,"distractorErrorTypes":null,"renderCheck":{"ok":true,"renderer":"std-1","checkedAt":"2026-10-20T16:19:24.600Z","issues":[]},"publish":true,"quality":{"contract":{"ok":true,"issues":[]},"estimatedDifficulty":"hard","requestedDifficulty":"hard","difficultyReasons":["앞 부등식의 정수 해가 뒤 단계의 입력이 되는 연쇄이며 올림·내림 선택이 결과를 바꿈 — medium 은 부등식 하나만 풀이"],"distractors":[],"independentReview":{"pickedIndex":null,"pickedAnswer":null,"agrees":true,"confidence":"high","flags":[]},"needsReview":false,"needsReviewReasons":[],"calibrated":false,"reviewedAt":"1970-01-01T00:00:00.000Z","mockExamGeneration":{"difficultyStatus":"provisional_ai","source":"compiler_archetype","archetypeId":"lib.ineq_applications.chain2","operator":"chain2","kind":"ineq_applications","extraThinking":"앞 부등식의 정수 해가 뒤 단계의 입력이 되는 연쇄이며 올림·내림 선택이 결과를 바꿈 — medium 은 부등식 하나만 풀이","concepts":["연쇄 부등식","올림·내림 판단","총량 계산"],"steps":5,"mediumSteps":2,"seed":820000,"variant":"min_trips_by_capacity","verification":{"method":"verification_js","verified":5,"correctOption":"5"},"runId":"sat-math-hard5","gid":"2f899045-1778-5948-a2c0-d5abf2ab6e3f","intendedSkill":"linear_inequalities","recipeId":"lib.ineq_applications.chain2","recipeCheck":{"source":"compiler_archetype","compliance":{"met":3,"minMet":2,"of":3,"ok":true}},"hardBasis":"compiler_archetype","review":null}}},{"gid":"cc96f57e-94a6-53dc-a39d-e9713159e32c","subject":"SAT Math","format":"mc","skillType":"Algebra (선형식·연립·부등식)","difficulty":"hard","skill":"linear_inequalities","examSystem":"sat_math","createdVia":"compiler","subpattern":"li.solve_one_var.param_condition/sign_of_coefficient","group":"li.solve_one_var.param_condition","passage":"Let k be a constant in the inequality below. The solution set of the inequality is all values of m that satisfy $m < -1$.\n\n$km - 6 < -12$","question":"What must k equal?","options":["-6","18","-1","6"],"correctIndex":3,"answers":null,"explanation":"(1) km 항만 남기도록 상수항을 이항하면 $km < -6$ 이다. (2) 해집합은 $m < -1$ 로, 원래 부등호 less than 와 방향이 같다. (3) 방향이 같으므로 양수로 나눈 것이다: k > 0 이다. (4) k 로 나누면 경계값은 -6/k 이다. (5) 경계값이 -1 이므로 -6/k = -1 이다. (6) k = -6/-1 = 6 이고 부호 조건과 맞는다. 따라서 정답은 6이다.","explanationEn":"(1) Isolate the K-term. (2) Compare the direction of the solution set with the original sign. (3) A flipped sign means division by a negative number. (4) Divide to get the boundary value. (5) Equate the boundary with the given value. (6) Solve and check the sign condition. So the answer is 6.","figure":null,"statements":null,"evidenceTarget":null,"evidenceSpan":null,"answerRationale":null,"distractorErrorTypes":null,"renderCheck":{"ok":true,"renderer":"std-1","checkedAt":"2026-10-20T16:19:24.600Z","issues":[]},"publish":true,"quality":{"contract":{"ok":true,"issues":[]},"estimatedDifficulty":"hard","requestedDifficulty":"hard","difficultyReasons":["해집합의 방향이 원래 부등호와 다르면 음수로 나눴다는 뜻이므로 k<0 이라는 암묵 조건을 읽어 내고 경계값 방정식으로 k 를 결정 — medium 은 주어진 부등식을 푸는 정방향"],"distractors":[],"independentReview":{"pickedIndex":null,"pickedAnswer":null,"agrees":true,"confidence":"high","flags":[]},"needsReview":false,"needsReviewReasons":[],"calibrated":false,"reviewedAt":"1970-01-01T00:00:00.000Z","mockExamGeneration":{"difficultyStatus":"provisional_ai","source":"compiler_archetype","archetypeId":"li.solve_one_var.param_condition","operator":"param_condition","kind":"solve_one_var","extraThinking":"해집합의 방향이 원래 부등호와 다르면 음수로 나눴다는 뜻이므로 k<0 이라는 암묵 조건을 읽어 내고 경계값 방정식으로 k 를 결정 — medium 은 주어진 부등식을 푸는 정방향","concepts":["부등식의 해집합","음수로 나눌 때 방향 반전","경계값 방정식"],"steps":6,"mediumSteps":2,"seed":820001,"variant":"sign_of_coefficient","verification":{"method":"verification_js","verified":6,"correctOption":"6"},"runId":"sat-math-hard5","gid":"cc96f57e-94a6-53dc-a39d-e9713159e32c","intendedSkill":"linear_inequalities","recipeId":"li.solve_one_var.param_condition","recipeCheck":{"source":"compiler_archetype","compliance":{"met":3,"minMet":2,"of":3,"ok":true}},"hardBasis":"compiler_archetype","review":null}}},{"gid":"8e66ef2c-4dc2-5c88-aaa1-0ae264a1a279","subject":"SAT Math","format":"mc","skillType":"Algebra (선형식·연립·부등식)","difficulty":"hard","skill":"linear_inequalities","examSystem":"sat_math","createdVia":"compiler","subpattern":"li.solve_one_var.constraint_select/compound_greatest","group":"li.solve_one_var.constraint_select","passage":"A value is chosen that satisfies both inequalities below.\n\n$5x + 1 \\le 5$\n$4x - 4 \\ge -33$","question":"Find the largest integer solution of both inequalities.","options":["-1","-7","1","0"],"correctIndex":3,"answers":null,"explanation":"(1) 첫 부등식을 풀면 $x \\ge -7.25$ (음수로 나누면 부등호 방향이 바뀐다). (2) 둘째 부등식을 풀면 $x \\le 0.8$. (3) 두 조건의 공통 구간(교집합)을 만든다. (4) 경계값이 포함되는지(≤, ≥ 인지 <, > 인지) 확인해 정수 후보를 정한다: -7, -6, -5, -4, -3, -2, -1, 0. (5) 가장 큰 정수는 0 이다. 따라서 정답은 0이다.","explanationEn":"(1) Solve the first inequality. (2) Solve the second inequality. (3) Intersect the two conditions. (4) List the integers allowed by the endpoints. (5) Answer the requested quantity. So the answer is 0.","figure":null,"statements":null,"evidenceTarget":null,"evidenceSpan":null,"answerRationale":null,"distractorErrorTypes":null,"renderCheck":{"ok":true,"renderer":"std-1","checkedAt":"2026-10-20T16:19:24.600Z","issues":[]},"publish":true,"quality":{"contract":{"ok":true,"issues":[]},"estimatedDifficulty":"hard","requestedDifficulty":"hard","difficultyReasons":["서로 다른 방향의 두 제약을 하나의 구간으로 합치고 경계 포함 여부를 따져 정수 후보를 걸러냄 — medium 은 부등식 하나의 해"],"distractors":[],"independentReview":{"pickedIndex":null,"pickedAnswer":null,"agrees":true,"confidence":"high","flags":[]},"needsReview":false,"needsReviewReasons":[],"calibrated":false,"reviewedAt":"1970-01-01T00:00:00.000Z","mockExamGeneration":{"difficultyStatus":"provisional_ai","source":"compiler_archetype","archetypeId":"li.solve_one_var.constraint_select","operator":"constraint_select","kind":"solve_one_var","extraThinking":"서로 다른 방향의 두 제약을 하나의 구간으로 합치고 경계 포함 여부를 따져 정수 후보를 걸러냄 — medium 은 부등식 하나의 해","concepts":["연립 부등식","구간의 교집합","정수 해 선택"],"steps":5,"mediumSteps":2,"seed":820000,"variant":"compound_greatest","verification":{"method":"verification_js","verified":0,"correctOption":"0"},"runId":"sat-math-hard5","gid":"8e66ef2c-4dc2-5c88-aaa1-0ae264a1a279","intendedSkill":"linear_inequalities","recipeId":"li.solve_one_var.constraint_select","recipeCheck":{"source":"compiler_archetype","compliance":{"met":3,"minMet":2,"of":3,"ok":true}},"hardBasis":"compiler_archetype","review":null}}},{"gid":"0846f7f1-77e3-5f71-a35c-aea6a3f79c26","subject":"SAT Math","format":"spr","skillType":"Algebra (선형식·연립·부등식)","difficulty":"hard","skill":"linear_inequalities","examSystem":"sat_math","createdVia":"compiler","subpattern":"li.solve_one_var.chain2/greatest_k","group":"li.solve_one_var.chain2","passage":"Among the integers satisfying $5m - 8 > 22$, the smallest is named s. For an integer k, the value s satisfies $km + 7 \\le 63$.","question":"What is the largest integer k can be?","options":null,"correctIndex":null,"answers":["8"],"explanation":"(1) 첫 부등식을 풀면 $m > 6$ 이다. (2) 부등호가 '>' 이므로 경계값은 해가 아니다. 그보다 큰 가장 작은 정수는 7 이다. (3) 둘째 부등식에 m = 7 를 대입하면 $k\\cdot 7 + 7 \\le 63$ 이다. (4) 상수를 이항하면 $7k \\le 56$ 이다. (5) 양수 7 로 나누면 $k \\le 8$ 이다. (6) K 는 정수이므로 가장 큰 값은 8 이다. 따라서 정답은 8이다.","explanationEn":"(1) Solve the first inequality. (2) The boundary is excluded, so take the next integer. (3) Substitute the value. (4) Isolate the K-term. (5) Divide by the positive number. (6) Take the extreme integer. So the answer is 8.","figure":null,"statements":null,"evidenceTarget":null,"evidenceSpan":null,"answerRationale":null,"distractorErrorTypes":null,"renderCheck":{"ok":true,"renderer":"std-1","checkedAt":"2026-10-20T16:19:24.600Z","issues":[]},"publish":true,"quality":{"contract":{"ok":true,"issues":[]},"estimatedDifficulty":"hard","requestedDifficulty":"hard","difficultyReasons":["앞 부등식의 결과(최소 정수 해)가 뒤 부등식의 입력 값이 되는 2단계 연쇄 — medium 은 부등식 하나의 해"],"distractors":[],"independentReview":{"pickedIndex":null,"pickedAnswer":null,"agrees":true,"confidence":"high","flags":[]},"needsReview":false,"needsReviewReasons":[],"calibrated":false,"reviewedAt":"1970-01-01T00:00:00.000Z","mockExamGeneration":{"difficultyStatus":"provisional_ai","source":"compiler_archetype","archetypeId":"li.solve_one_var.chain2","operator":"chain2","kind":"solve_one_var","extraThinking":"앞 부등식의 결과(최소 정수 해)가 뒤 부등식의 입력 값이 되는 2단계 연쇄 — medium 은 부등식 하나의 해","concepts":["부등식 풀이","최소 정수 해","대입 후 매개변수 부등식"],"steps":6,"mediumSteps":2,"seed":820000,"variant":"greatest_k","verification":{"method":"verification_js","verified":8,"correctOption":"8"},"runId":"sat-math-hard5","gid":"0846f7f1-77e3-5f71-a35c-aea6a3f79c26","intendedSkill":"linear_inequalities","recipeId":"li.solve_one_var.chain2","recipeCheck":{"source":"compiler_archetype","compliance":{"met":3,"minMet":2,"of":3,"ok":true}},"hardBasis":"compiler_archetype","review":null}}},{"gid":"f6910e7e-6f29-578b-aca9-c0a2cf81fb56","subject":"SAT Math","format":"mc","skillType":"Algebra (선형식·연립·부등식)","difficulty":"hard","skill":"linear_inequalities","examSystem":"sat_math","createdVia":"compiler","subpattern":"li.solve_one_var.compose_kind/perimeter_area_bound","group":"li.solve_one_var.compose_kind","passage":"The length of a rectangular garden is $x + 2$ meters and its width is $x - 1$ meters, for an integer x. The distance around it is no more than 45 meters. The width must be at least 3 meters.","question":"Find the maximum possible area of the garden in square meters.","options":["18","108","130","45"],"correctIndex":1,"answers":null,"explanation":"(1) 둘레는 $2((x + 2) + (x - 1)) = 4 x + 2$ 이다. (2) 둘레 조건 $4x + 2 \\le 45$ 에서 $x \\le 10.75$ 이다. (3) 세로 조건 $x - 1 \\ge 3$ 에서 $x \\ge 4$ 이다. (4) 정수 x 의 범위는 4 이상 10 이하이다. (5) 가로·세로가 모두 x 와 함께 커지므로 넓이는 x 가 클수록 크다. (6) x = 10 일 때 가로 12, 세로 9 이고 넓이는 108 이다. 따라서 정답은 108이다.","explanationEn":"(1) Write the perimeter. (2) Solve the perimeter inequality. (3) Solve the width inequality. (4) Combine into an integer range. (5) Area increases with x. (6) Evaluate at the greatest x. So the answer is 108.","figure":null,"statements":null,"evidenceTarget":null,"evidenceSpan":null,"answerRationale":null,"distractorErrorTypes":null,"renderCheck":{"ok":true,"renderer":"std-1","checkedAt":"2026-10-20T16:19:24.601Z","issues":[]},"publish":true,"quality":{"contract":{"ok":true,"issues":[]},"estimatedDifficulty":"hard","requestedDifficulty":"hard","difficultyReasons":["부등식을 둘레·넓이 공식과 합성하고, 넓이가 x 에 대해 증가함을 이용해 정수 구간의 끝값을 선택 — medium 은 부등식 하나의 해"],"distractors":[],"independentReview":{"pickedIndex":null,"pickedAnswer":null,"agrees":true,"confidence":"high","flags":[]},"needsReview":false,"needsReviewReasons":[],"calibrated":false,"reviewedAt":"1970-01-01T00:00:00.000Z","mockExamGeneration":{"difficultyStatus":"provisional_ai","source":"compiler_archetype","archetypeId":"li.solve_one_var.compose_kind","operator":"compose_kind","kind":"solve_one_var","extraThinking":"부등식을 둘레·넓이 공식과 합성하고, 넓이가 x 에 대해 증가함을 이용해 정수 구간의 끝값을 선택 — medium 은 부등식 하나의 해","concepts":["일차부등식","직사각형 둘레와 넓이","정수 구간의 끝값"],"steps":6,"mediumSteps":2,"seed":820001,"variant":"perimeter_area_bound","verification":{"method":"verification_js","verified":108,"correctOption":"108"},"runId":"sat-math-hard5","gid":"f6910e7e-6f29-578b-aca9-c0a2cf81fb56","intendedSkill":"linear_inequalities","recipeId":"li.solve_one_var.compose_kind","recipeCheck":{"source":"compiler_archetype","compliance":{"met":3,"minMet":2,"of":3,"ok":true}},"hardBasis":"compiler_archetype","review":null}}},{"gid":"34b794bb-5e89-52b1-ad27-4d13087c51d1","subject":"SAT Math","format":"mc","skillType":"Algebra (선형식·연립·부등식)","difficulty":"hard","skill":"linear_inequalities","examSystem":"sat_math","createdVia":"compiler","subpattern":"li.point_in_solution.inverse/unknown_constant_count","group":"li.point_in_solution.inverse","passage":"An integer b appears in the inequality below. The coordinates $(1, 6)$ make the inequality true.\n\n$y \\le x + b$","question":"Among the integers from -7 to 7, inclusive, how many can be the value of b?","options":["15","3","2","4"],"correctIndex":1,"answers":null,"explanation":"(1) 점 (1, 6) 를 대입하면 $6 \\le 1\\cdot 1 + b$ 이다. (2) 정리하면 $6 \\le 1 + b$ 이다. (3) b 에 대해 풀면 $b \\ge 5$ 이다. (4) 경계값 5 가 포함된다. (5) 정수 범위 -7 이상 7 이하와 겹치는 정수를 센다. (6) 가능한 정수 b 는 3개이다. 따라서 정답은 3이다.","explanationEn":"(1) Substitute the point. (2) Simplify. (3) Solve for b. (4) Decide whether the endpoint is included. (5) Intersect with the allowed range. (6) Count. So the answer is 3.","figure":null,"statements":null,"evidenceTarget":null,"evidenceSpan":null,"answerRationale":null,"distractorErrorTypes":null,"renderCheck":{"ok":true,"renderer":"std-1","checkedAt":"2026-10-20T16:19:24.601Z","issues":[]},"publish":true,"quality":{"contract":{"ok":true,"issues":[]},"estimatedDifficulty":"hard","requestedDifficulty":"hard","difficultyReasons":["점을 대입한 결과를 미지 상수에 대한 부등식으로 거꾸로 풀고 경계 포함 여부와 범위 제한을 함께 처리 — medium 은 점이 해인지 판정하는 정방향"],"distractors":[],"independentReview":{"pickedIndex":null,"pickedAnswer":null,"agrees":true,"confidence":"high","flags":[]},"needsReview":false,"needsReviewReasons":[],"calibrated":false,"reviewedAt":"1970-01-01T00:00:00.000Z","mockExamGeneration":{"difficultyStatus":"provisional_ai","source":"compiler_archetype","archetypeId":"li.point_in_solution.inverse","operator":"inverse","kind":"point_in_solution","extraThinking":"점을 대입한 결과를 미지 상수에 대한 부등식으로 거꾸로 풀고 경계 포함 여부와 범위 제한을 함께 처리 — medium 은 점이 해인지 판정하는 정방향","concepts":["점의 대입","미지 상수에 대한 부등식","정수 개수 세기"],"steps":6,"mediumSteps":2,"seed":820000,"variant":"unknown_constant_count","verification":{"method":"verification_js","verified":3,"correctOption":"3"},"runId":"sat-math-hard5","gid":"34b794bb-5e89-52b1-ad27-4d13087c51d1","intendedSkill":"linear_inequalities","recipeId":"li.point_in_solution.inverse","recipeCheck":{"source":"compiler_archetype","compliance":{"met":3,"minMet":2,"of":3,"ok":true}},"hardBasis":"compiler_archetype","review":null}}},{"gid":"dbc4c3a4-62c8-5a90-a533-164821bcb559","subject":"SAT Math","format":"spr","skillType":"Algebra (선형식·연립·부등식)","difficulty":"hard","skill":"linear_inequalities","examSystem":"sat_math","createdVia":"compiler","subpattern":"li.point_in_solution.constraint_select/lattice_between_lines","group":"li.point_in_solution.constraint_select","passage":"Look at the two inequalities below.\n\n$y > 2x + 1$\n$y \\le x + 8$\n\nOnly points whose coordinates are positive integers and whose x-coordinate is at most 5 are counted.","question":"What is the total number of points that satisfy both conditions?","options":null,"correctIndex":null,"answers":["20"],"explanation":"(1) 두 부등식을 각 x 에 대해 y 의 범위로 읽는다. (2) x = 1: y 는 3 보다 커야 하고 9 보다 작거나 같아야 하며 양의 정수이므로 6개이다. (3) x = 2: y 는 5 보다 커야 하고 10 보다 작거나 같아야 하며 양의 정수이므로 5개이다. (4) x = 3: y 는 7 보다 커야 하고 11 보다 작거나 같아야 하며 양의 정수이므로 4개이다. (5) x = 4: y 는 9 보다 커야 하고 12 보다 작거나 같아야 하며 양의 정수이므로 3개이다. (6) x = 5: y 는 11 보다 커야 하고 13 보다 작거나 같아야 하며 양의 정수이므로 2개이다. (7) 열별 개수를 모두 더하면 6 + 5 + 4 + 3 + 2 = 20 이다. 따라서 정답은 20이다.","explanationEn":"(1) Read both as bounds on y for each x. (2) For x = 1 count the allowed y. (3) For x = 2 count the allowed y. (4) For x = 3 count the allowed y. (5) For x = 4 count the allowed y. (6) For x = 5 count the allowed y. (7) Add the counts. So the answer is 20.","figure":null,"statements":null,"evidenceTarget":null,"evidenceSpan":null,"answerRationale":null,"distractorErrorTypes":null,"renderCheck":{"ok":true,"renderer":"std-1","checkedAt":"2026-10-20T16:19:24.601Z","issues":[]},"publish":true,"quality":{"contract":{"ok":true,"issues":[]},"estimatedDifficulty":"hard","requestedDifficulty":"hard","difficultyReasons":["각 x 마다 y 의 허용 구간(포함 여부 포함)을 따로 구해 격자점을 선택·합산 — medium 은 점 하나가 해인지 판정"],"distractors":[],"independentReview":{"pickedIndex":null,"pickedAnswer":null,"agrees":true,"confidence":"high","flags":[]},"needsReview":false,"needsReviewReasons":[],"calibrated":false,"reviewedAt":"1970-01-01T00:00:00.000Z","mockExamGeneration":{"difficultyStatus":"provisional_ai","source":"compiler_archetype","archetypeId":"li.point_in_solution.constraint_select","operator":"constraint_select","kind":"point_in_solution","extraThinking":"각 x 마다 y 의 허용 구간(포함 여부 포함)을 따로 구해 격자점을 선택·합산 — medium 은 점 하나가 해인지 판정","concepts":["연립 부등식의 영역","격자점 세기","경계 포함 여부"],"steps":7,"mediumSteps":2,"seed":820000,"variant":"lattice_between_lines","verification":{"method":"verification_js","verified":20,"correctOption":"20"},"runId":"sat-math-hard5","gid":"dbc4c3a4-62c8-5a90-a533-164821bcb559","intendedSkill":"linear_inequalities","recipeId":"li.point_in_solution.constraint_select","recipeCheck":{"source":"compiler_archetype","compliance":{"met":3,"minMet":2,"of":3,"ok":true}},"hardBasis":"compiler_archetype","review":null}}},{"gid":"fbdaf312-9cdf-5783-ab10-82a9f7e59a55","subject":"SAT Math","format":"mc","skillType":"Algebra (선형식·연립·부등식)","difficulty":"hard","skill":"linear_inequalities","examSystem":"sat_math","createdVia":"compiler","subpattern":"li.point_in_solution.repr_shift/revenue_goal_round_up","group":"li.point_in_solution.repr_shift","passage":"A school play sells adult tickets for 11 dollars each and student tickets for 4 dollars each. The goal is to earn at least 427 dollars in total. So far, 30 adult tickets have been sold.","question":"What is the least number of student tickets that must also be sold to reach the goal?","options":["26","24","107","25"],"correctIndex":3,"answers":null,"explanation":"(1) adult ticket 수를 x, student ticket 수를 y 라 하면 수입은 $11x + 4y$ 이다. (2) 목표는 $11x + 4y \\ge 427$ 이다. (3) x = 30 를 대입하면 $4y \\ge 97$ 이다. (4) 4 로 나누면 $y \\ge 24.25$ 이다. (5) 판매 수는 정수이므로 올림한다. (6) 최소 판매 수는 25 이다. 따라서 정답은 25이다.","explanationEn":"(1) Model total revenue. (2) Write the goal as an inequality. (3) Substitute the known count. (4) Divide. (5) Counts are whole numbers, so round up. (6) Answer. So the answer is 25.","figure":null,"statements":null,"evidenceTarget":null,"evidenceSpan":null,"answerRationale":null,"distractorErrorTypes":null,"renderCheck":{"ok":true,"renderer":"std-1","checkedAt":"2026-10-20T16:19:24.601Z","issues":[]},"publish":true,"quality":{"contract":{"ok":true,"issues":[]},"estimatedDifficulty":"hard","requestedDifficulty":"hard","difficultyReasons":["문장을 두 변수 부등식으로 모델링하고 한 변수를 대입한 뒤 정수 조건(올림)을 적용 — medium 은 주어진 부등식에 점을 대입해 판정"],"distractors":[],"independentReview":{"pickedIndex":null,"pickedAnswer":null,"agrees":true,"confidence":"high","flags":[]},"needsReview":false,"needsReviewReasons":[],"calibrated":false,"reviewedAt":"1970-01-01T00:00:00.000Z","mockExamGeneration":{"difficultyStatus":"provisional_ai","source":"compiler_archetype","archetypeId":"li.point_in_solution.repr_shift","operator":"repr_shift","kind":"point_in_solution","extraThinking":"문장을 두 변수 부등식으로 모델링하고 한 변수를 대입한 뒤 정수 조건(올림)을 적용 — medium 은 주어진 부등식에 점을 대입해 판정","concepts":["문장→두 변수 부등식","대입","정수 조건과 올림"],"steps":6,"mediumSteps":2,"seed":820001,"variant":"revenue_goal_round_up","verification":{"method":"verification_js","verified":25,"correctOption":"25"},"runId":"sat-math-hard5","gid":"fbdaf312-9cdf-5783-ab10-82a9f7e59a55","intendedSkill":"linear_inequalities","recipeId":"li.point_in_solution.repr_shift","recipeCheck":{"source":"compiler_archetype","compliance":{"met":3,"minMet":2,"of":3,"ok":true}},"hardBasis":"compiler_archetype","review":null}}},{"gid":"6c86d8ad-00fd-5eba-afba-54022b248537","subject":"SAT Math","format":"mc","skillType":"Algebra (선형식·연립·부등식)","difficulty":"hard","skill":"linear_inequalities","examSystem":"sat_math","createdVia":"compiler","subpattern":"li.point_in_solution.compare_scenarios/plan_crossover","group":"li.point_in_solution.compare_scenarios","passage":"Two plans are offered by a print shop. Plan A costs 7 dollars for each poster plus a setup charge of 50 dollars. Plan B has a setup charge of 85 dollars and charges 4 dollars per poster. Only whole numbers of posters can be purchased.","question":"For what least whole number of posters is Plan B cheaper than Plan A?","options":["12","13","22","11"],"correctIndex":0,"answers":null,"explanation":"(1) Plan A 의 비용은 $50 + 7n$ 이다. (2) Plan B 의 비용은 $85 + 4n$ 이다. (3) B 가 더 싸려면 $85 + 4n < 50 + 7n$ 이어야 한다. (4) n 항을 모으면 $35 < 3n$ 이다. (5) $n > 11.67$ 이다. (6) 경계  다음 정수는 12 이다. 따라서 정답은 12이다.","explanationEn":"(1) Write Plan A's cost. (2) Write Plan B's cost. (3) Write the comparison. (4) Collect n terms. (5) Divide. (6) Take the next whole number. So the answer is 12.","figure":null,"statements":null,"evidenceTarget":null,"evidenceSpan":null,"answerRationale":null,"distractorErrorTypes":null,"renderCheck":{"ok":true,"renderer":"std-1","checkedAt":"2026-10-20T16:19:24.601Z","issues":[]},"publish":true,"quality":{"contract":{"ok":true,"issues":[]},"estimatedDifficulty":"hard","requestedDifficulty":"hard","difficultyReasons":["서로 다른 고정비와 단위비용의 두 비용식을 비교하는 부등식을 세우고 임계점 직후의 정수를 선택 — medium 은 주어진 하나의 식에 대입"],"distractors":[],"independentReview":{"pickedIndex":null,"pickedAnswer":null,"agrees":true,"confidence":"high","flags":[]},"needsReview":false,"needsReviewReasons":[],"calibrated":false,"reviewedAt":"1970-01-01T00:00:00.000Z","mockExamGeneration":{"difficultyStatus":"provisional_ai","source":"compiler_archetype","archetypeId":"li.point_in_solution.compare_scenarios","operator":"compare_scenarios","kind":"point_in_solution","extraThinking":"서로 다른 고정비와 단위비용의 두 비용식을 비교하는 부등식을 세우고 임계점 직후의 정수를 선택 — medium 은 주어진 하나의 식에 대입","concepts":["두 비용식 모델링","비교 부등식","임계점과 정수 선택"],"steps":6,"mediumSteps":2,"seed":820001,"variant":"plan_crossover","verification":{"method":"verification_js","verified":12,"correctOption":"12"},"runId":"sat-math-hard5","gid":"6c86d8ad-00fd-5eba-afba-54022b248537","intendedSkill":"linear_inequalities","recipeId":"li.point_in_solution.compare_scenarios","recipeCheck":{"source":"compiler_archetype","compliance":{"met":3,"minMet":2,"of":3,"ok":true}},"hardBasis":"compiler_archetype","review":null}}},{"gid":"316e2cb2-e778-5377-af1c-100610e9ec49","subject":"SAT Math","format":"spr","skillType":"Algebra (선형식·연립·부등식)","difficulty":"hard","skill":"linear_inequalities","examSystem":"sat_math","createdVia":"compiler","subpattern":"li.table_verification.repr_shift/sentence_to_inequality","group":"li.table_verification.repr_shift","passage":"Consider the statement below about ordered pairs (x, y): the y-coordinate must be greater than 5 more than 2 times the x-value. Here are the pairs $(-3, 2)$, $(-2, 2)$, $(1, 4)$, $(2, 9)$, $(3, 8)$, and $(4, 10)$.","question":"For how many of the ordered pairs is the statement true?","options":null,"correctIndex":null,"answers":["2"],"explanation":"(1) 문장을 식으로 번역한다: $y > 2x + 5$. (2) (-3, 2): 우변 -1, 좌변 2 → 참. (3) (-2, 2): 우변 1, 좌변 2 → 참. (4) (1, 4): 우변 7, 좌변 4 → 거짓. (5) (2, 9): 우변 9, 좌변 9 → 거짓. (6) (3, 8): 우변 11, 좌변 8 → 거짓. (7) (4, 10): 우변 13, 좌변 10 → 거짓. (8) 참인 쌍은 2개이다. 따라서 정답은 2이다.","explanationEn":"(1) Translate the sentence. (2) Test the pair (-3, 2). (3) Test the pair (-2, 2). (4) Test the pair (1, 4). (5) Test the pair (2, 9). (6) Test the pair (3, 8). (7) Test the pair (4, 10). (8) Count the true cases. So the answer is 2.","figure":null,"statements":null,"evidenceTarget":null,"evidenceSpan":null,"answerRationale":null,"distractorErrorTypes":null,"renderCheck":{"ok":true,"renderer":"std-1","checkedAt":"2026-10-20T16:19:24.601Z","issues":[]},"publish":true,"quality":{"contract":{"ok":true,"issues":[]},"estimatedDifficulty":"hard","requestedDifficulty":"hard","difficultyReasons":["문장 서술을 부등식 기호와 방향으로 정확히 번역(m 배보다 b 큰 → mx + b)하고 경계 위 점을 포함 여부로 판정 — medium 은 식이 주어진 상태에서 검증"],"distractors":[],"independentReview":{"pickedIndex":null,"pickedAnswer":null,"agrees":true,"confidence":"high","flags":[]},"needsReview":false,"needsReviewReasons":[],"calibrated":false,"reviewedAt":"1970-01-01T00:00:00.000Z","mockExamGeneration":{"difficultyStatus":"provisional_ai","source":"compiler_archetype","archetypeId":"li.table_verification.repr_shift","operator":"repr_shift","kind":"table_verification","extraThinking":"문장 서술을 부등식 기호와 방향으로 정확히 번역(m 배보다 b 큰 → mx + b)하고 경계 위 점을 포함 여부로 판정 — medium 은 식이 주어진 상태에서 검증","concepts":["문장→부등식 번역","순서쌍 대입 검증","경계 포함 여부"],"steps":8,"mediumSteps":4,"seed":820001,"variant":"sentence_to_inequality","verification":{"method":"verification_js","verified":2,"correctOption":"2"},"runId":"sat-math-hard5","gid":"316e2cb2-e778-5377-af1c-100610e9ec49","intendedSkill":"linear_inequalities","recipeId":"li.table_verification.repr_shift","recipeCheck":{"source":"compiler_archetype","compliance":{"met":3,"minMet":2,"of":3,"ok":true}},"hardBasis":"compiler_archetype","review":null}}},{"gid":"ee1e4d13-5934-5d01-a7ef-e25caaac8682","subject":"SAT Math","format":"mc","skillType":"Algebra (선형식·연립·부등식)","difficulty":"hard","skill":"linear_inequalities","examSystem":"sat_math","createdVia":"compiler","subpattern":"lib.ineq_applications.constraint_select/abs_count_integers","group":"lib.ineq_applications.constraint_select","passage":"A short exercise in a math magazine describes the setting below. Consider the inequality $|4x - 1| < 25$, where x is an integer. None of the details were altered after they were first recorded.","question":"For how many integers x is the inequality true?","options":["6","13","12","11"],"correctIndex":2,"answers":null,"explanation":"(1) 절댓값 부등식은 −25 < 4x − 1 < 25 로 쓸 수 있다. (2) 각 변에 1 를 더하면 -24 < 4x < 26 이다. (3) 4 로 나누면 -6.00 < x < 6.50 이다. (4) 양 끝은 포함되지 않는다. (5) 그 사이의 정수는 12 개이다. 따라서 정답은 12이다.","explanationEn":"(1) Rewrite the absolute value inequality as a compound inequality. (2) Add the constant to all parts. (3) Divide by the coefficient. (4) Endpoints are excluded. (5) Count the integers. So the answer is 12.","figure":null,"statements":null,"evidenceTarget":null,"evidenceSpan":null,"answerRationale":null,"distractorErrorTypes":null,"renderCheck":{"ok":true,"renderer":"std-1","checkedAt":"2026-10-20T16:19:24.601Z","issues":[]},"publish":true,"quality":{"contract":{"ok":true,"issues":[]},"estimatedDifficulty":"hard","requestedDifficulty":"hard","difficultyReasons":["제약을 스스로 부등식으로 세우고 경계 포함 여부와 정수 조건으로 해를 골라야 함 — medium 은 주어진 일차부등식 하나의 해"],"distractors":[],"independentReview":{"pickedIndex":null,"pickedAnswer":null,"agrees":true,"confidence":"high","flags":[]},"needsReview":false,"needsReviewReasons":[],"calibrated":false,"reviewedAt":"1970-01-01T00:00:00.000Z","mockExamGeneration":{"difficultyStatus":"provisional_ai","source":"compiler_archetype","archetypeId":"lib.ineq_applications.constraint_select","operator":"constraint_select","kind":"ineq_applications","extraThinking":"제약을 스스로 부등식으로 세우고 경계 포함 여부와 정수 조건으로 해를 골라야 함 — medium 은 주어진 일차부등식 하나의 해","concepts":["부등식 모델링","경계 포함 여부","정수 해 선택"],"steps":5,"mediumSteps":2,"seed":820001,"variant":"abs_count_integers","verification":{"method":"verification_js","verified":12,"correctOption":"12"},"runId":"sat-math-hard5","gid":"ee1e4d13-5934-5d01-a7ef-e25caaac8682","intendedSkill":"linear_inequalities","recipeId":"lib.ineq_applications.constraint_select","recipeCheck":{"source":"compiler_archetype","compliance":{"met":3,"minMet":2,"of":3,"ok":true}},"hardBasis":"compiler_archetype","review":null}}},{"gid":"419fc5d2-6ffc-5267-a6fa-dd1b3c2b44f9","subject":"SAT Math","format":"mc","skillType":"Algebra (선형식·연립·부등식)","difficulty":"hard","skill":"linear_inequalities","examSystem":"sat_math","createdVia":"compiler","subpattern":"lib.ineq_applications.compare_scenarios/cost_per_person_min_people","group":"lib.ineq_applications.compare_scenarios","passage":"Consider the scenario described in the paragraph below. A club rents a banquet hall for a flat fee of 110 dollars, and each guest also pays 10 dollars for food. The club wants the average cost per guest, counting the flat fee, to be at most 13 dollars. These are the only facts that were noted at the time.","question":"What is the smallest number of guests that makes this possible?","options":["37","11","36","9"],"correctIndex":0,"answers":null,"explanation":"(1) 손님 n 명의 총비용은 110 + 10n 이다. (2) 1인당 평균 비용은 (110 + 10n)/n 이다. (3) (110 + 10n)/n ≤ 13 에서 110 ≤ 3n 이다. (4) n ≥ 110/3 = 36.67 이다. (5) 정수이므로 최소 37 명이다. 따라서 정답은 37이다.","explanationEn":"(1) Total cost. (2) Average per guest. (3) Clear the fraction. (4) Solve. (5) Round up. So the answer is 37.","figure":null,"statements":null,"evidenceTarget":null,"evidenceSpan":null,"answerRationale":null,"distractorErrorTypes":null,"renderCheck":{"ok":true,"renderer":"std-1","checkedAt":"2026-10-20T16:19:24.601Z","issues":[]},"publish":true,"quality":{"contract":{"ok":true,"issues":[]},"estimatedDifficulty":"hard","requestedDifficulty":"hard","difficultyReasons":["두 조건·두 대상의 식을 같은 변수로 맞춘 뒤 공통 해를 찾아야 함 — medium 은 한 식의 부등식 풀이"],"distractors":[],"independentReview":{"pickedIndex":null,"pickedAnswer":null,"agrees":true,"confidence":"high","flags":[]},"needsReview":false,"needsReviewReasons":[],"calibrated":false,"reviewedAt":"1970-01-01T00:00:00.000Z","mockExamGeneration":{"difficultyStatus":"provisional_ai","source":"compiler_archetype","archetypeId":"lib.ineq_applications.compare_scenarios","operator":"compare_scenarios","kind":"ineq_applications","extraThinking":"두 조건·두 대상의 식을 같은 변수로 맞춘 뒤 공통 해를 찾아야 함 — medium 은 한 식의 부등식 풀이","concepts":["두 식 비교","구간의 교집합","정수 경계"],"steps":5,"mediumSteps":2,"seed":820001,"variant":"cost_per_person_min_people","verification":{"method":"verification_js","verified":37,"correctOption":"37"},"runId":"sat-math-hard5","gid":"419fc5d2-6ffc-5267-a6fa-dd1b3c2b44f9","intendedSkill":"linear_inequalities","recipeId":"lib.ineq_applications.compare_scenarios","recipeCheck":{"source":"compiler_archetype","compliance":{"met":3,"minMet":2,"of":3,"ok":true}},"hardBasis":"compiler_archetype","review":null}}}]$satx$::jsonb;
  v_actor uuid := (select id from profiles where role = 'admin' order by created_at limit 1);
  r jsonb; v_pid uuid; v_vid uuid; v_n int := 0; v_skip int := 0;
begin
  if v_actor is null then raise exception 'No admin profile found.'; end if;
  for r in select * from jsonb_array_elements(v_items) loop
    if exists (select 1 from problem_versions where quality->'mockExamGeneration'->>'gid' = r->>'gid') then v_skip := v_skip + 1; continue; end if;
    v_pid := public.create_bank_problem(p_subject_id => (select id from subjects where name = r->>'subject' and archived_at is null), p_format => r->>'format', p_skill_type => r->>'skillType', p_topic => '',
      p_difficulty => r->>'difficulty', p_actor_id => v_actor, p_skill_code => r->>'skill', p_exam_system => r->>'examSystem', p_ap_subject => null, p_usage_scope => 'mock_exam');
    update problems set created_via = r->>'createdVia', subpattern = coalesce(r->>'subpattern', subpattern), similarity_group = coalesce(r->>'group', similarity_group) where id = v_pid;
    v_vid := public.save_problem_draft_version(p_problem_id => v_pid, p_passage => r->>'passage', p_options => nullif(r->'options', 'null'::jsonb), p_correct_index => (r->>'correctIndex')::int, p_explanation => r->>'explanation',
      p_difficulty => r->>'difficulty', p_actor_id => v_actor, p_answers => nullif(r->'answers', 'null'::jsonb), p_figure => nullif(r->'figure', 'null'::jsonb), p_figure_checked => false, p_statements => nullif(r->'statements', 'null'::jsonb),
      p_question => r->>'question', p_repair_status => null, p_explanation_en => r->>'explanationEn', p_evidence_target => r->>'evidenceTarget', p_evidence_span => r->>'evidenceSpan', p_answer_rationale => r->>'answerRationale',
      p_distractor_error_types => nullif(r->'distractorErrorTypes', 'null'::jsonb));
    perform public.set_problem_render_check(v_vid, r->'renderCheck');
    perform public.set_problem_quality(v_vid, r->'quality');
    if (r->>'publish')::boolean then perform public.confirm_and_publish_problem_version(v_vid, v_actor); end if;
    v_n := v_n + 1;
  end loop;
  raise notice 'SAT Math hard import (math hard5) 1/1: created=% skipped(existing)=%', v_n, v_skip;
end
